quests[78154] = { id = 78154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Probe stellen: Rune der Schattenbindung", description = "Wir müssen die Bindung abschließen. Wir können die Komponenten richtig einstimmen, indem wir sie im Kampf gegen Fyrakks mächtigste Leutnants erproben. Dann können wir die eingestimmten Materialien an Fyr'alath binden.\n\nWenn Ihr Knorrenwurzel, Igira die Grausame und Volcoross besiegen könnt, während diese Rune an sie gebunden ist, seid Ihr bereit, die Rune der Schattenbindung vollständig einzustimmen.", sourceObjective = "Besiegt Knorrenwurzel, Igira die Grausame und Wolokreuz in Amirdrassil, Hoffnung des Traums.", completion = "Wie aufregend! Ich bin eine Handwerkerin, keine Kämpferin, aber Eure Kampffähigkeiten sind beeindruckend!", sourceObjectiveStatus = "unverified-source-field" }
quests[78155] = { id = 78155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Leuchtende Ascheflocke", description = "Ich habe gehört, dass im Smaragdgrünen Traum eine raue Asche mit starken Schattenflammeneigenschaften existiert, die an mächtiger Ausrüstung haften bleibt. Die einzige Art, diesen mächtigen Staub zu ernten, ist das Zerlegen der Ausrüstung.\n\nHier, nehmt diese Rute, die ich verzaubert habe. Damit solltet Ihr den Staub gewinnen können, den Ihr braucht.", sourceObjective = "Sammelt leuchtende Ascheflocken von mächtiger Ausrüstung im Smaragdgrünen Traum.", progress = "Gebt nicht auf! Dieser Vorgang hilft nicht nur bei der Fertigung. Er formt auch den Charakter! Denkt daran!", completion = "Ich hoffe, die Wünschelrute hat geholfen! Nun zum nächsten Schritt...", sourceObjectiveStatus = "unverified-source-field" }
quests[78156] = { id = 78156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Strahlendes Pergament", description = "Wir können meine Schöpfung verfeinern, indem wir Ordnungsmagie in die Verzauberung einfügen.\n\nHier sind meine Notizen zu konzentriertem weisem Pergament. Teilt dies mit einem anderen befreundeten Verzauberer, dann sollte dieser genug Informationen haben, um einen Handwerksauftrag für Euch auszuführen.", sourceObjective = "Fertigt oder erlangt Shalasars weises Pergament.", progress = "Ich habe gesehen, wie diese Art von Aufgabe dazu führte, dass der Beruf für Schüler jeden... Zauber... verlor, aber ich weiß, dass Ihr aus härterem Holz geschnitzt seid.\n\nEs tut mir leid. Ich war lange Zeit allein und konnte diesen \"Witz\" lange nicht anbringen.", completion = "Fast geschafft. Jetzt müssen wir es nur noch schaffen, dass die im Widerstreit stehende Schattenflamme und Ordnungsmagie zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78159] = { id = 78159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung: Leuchtsporengriff", description = "Um etwas Funktionierendes zu fertigen, werden wir große Mengen Zaralekleuchtsporen und etwas Leder brauchen.\n\nHier sind meine Notizen zum symbiotischen Leuchtsporengriff. Teilt sie mit einem befreundeten Lederverarbeiter, dann sollte dieser genug Informationen haben und Euch einen Handwerksauftrag erfüllen können.", sourceObjective = "Fertigt oder erlangt Erdens Leuchtsporengriff.", progress = "Es ist eine Menge Arbeit, dies zu finden, aber die Beute ist die Jagd wert.", completion = "Zeit für den letzten Schritt. Das könnte etwas... unangenehm werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78160] = { id = 78160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Probe stellen: Symbiotischer Leuchtsporengriff", description = "Ihr werdet mir vertrauen müssen. Wir müssen die Reagenzien aktivieren, die in diesen Griff eingebettet sind.\n\nWenn wir den Griff um Schaft von Fyr'alath wickeln, sollte das funktionieren, solange Ihr den Ansturm überlebt, der folgen wird. Ihr werdet währenddessen Anpassungen vornehmen müssen, also wird es nicht beim ersten Mal klappen. Die Sporen müssen sich an die Axt anpassen.", sourceObjective = "Ermächtigt den Griff, während Ihr seine Vereinigung mit Fyr'alath überlebt.", progress = "Nur weiter so. All diese harte Arbeit wird sich auszahlen.", completion = "Gute Arbeit. Dieser Griff sollte Euch gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78162] = { id = 78162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Q'onzus Ablenkung", description = "Eure Fragen sind mir wirklich wichtig. Leider bin ich einfach zu abgelenkt.\n\nDiese Schotlinge... schreckliche kleine Kreaturen. Ihr habt sie sicher gesehen. Sie dringen in mein Nest ein und sind einfach unglaublich störend.\n\nMich und meine Freunde stören? Wie unerhört! Hier ist meine Feder. Warum macht Ihr aus diesen Störungen nicht etwas weniger Störendes.", sourceObjective = "Schwächt 8 Schotlinge und benutzt dann Q'onzus Feenfeder, um aus ihnen Feendrachen zu machen.", progress = "Ich kann immer noch die nervigen Geräusche dieser Schotlinge hören. Es ist eine Folter.", completion = "Ihr schon wieder? Was habt Ihr getan? Oh, ja. Das ist in Ordnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[78163] = { id = 78163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Q'onzus Qualifikation", description = "Ihr möchtet eine Audienz bei Q'onzu, aber Ihr kommt ohne Opfergaben?\n\nMan marschiert nicht einfach herein und spricht mit dem Loa der Veränderung, fürchte ich. Zuerst müsst Ihr beweisen, dass Ihr die Aufmerksamkeit wert seid.\n\nDie Freunde von Q'onzu erhielten einhundert Fragen vom Loa selbst! Ihr müsst Euren Verstand beweisen und jede einzelne richtig beantworten.\n\nKehrt zu mir zurück, wenn Ihr alle einhundert beantwortet habt. Dann erhaltet Ihr vielleicht eine Audienz.", sourceObjective = "Beantwortet Q'onzus 100 Fragen.", completion = "Ihr hättet wirklich 100 Fragen beantwortet? Ich dachte einfach, dass Ihr dann fortgehen würdet.\n\nNächstes Mal gehe ich hoch auf eintausend Fragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78170] = { id = 78170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alterslose Samen pflegen", description = "Das Wachstum dieser Saaten erfordert eine empfindliche Balance und permanente Fürsorge.\n\nIch habe herausgefunden, dass zeitlose Tautropfen aus dieser Gegend eine spezielle Energie enthalten, die das schlummernde Potenzial dieser Saaten wecken kann.\n\nWenn Ihr einige Tautropfen sammelt und sie auf die Pflanzen anwendet, könnt Ihr deren volles Potenzial entfalten.", sourceObjective = "Pflegt jeden der gepflanzten Samen mit zeitlosen Tautropfen.", progress = "Habt Ihr den aufblühenden Samen die zeitlosen Tautropfen gegeben?", completion = "Danke, {name}. Eure Bereitschaft, bei der Pflege dieser uralten Samen zu helfen, wärmt mir das Herz.", sourceObjectiveStatus = "unverified-source-field" }
quests[78171] = { id = 78171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blüten der Vergangenheit", description = "Mit Eurer Hilfe sind diese Samen zu majestätischen Pflanzen herangewachsen. Aber der aufregendste Teil kommt erst noch.\n\nJede Blüte dieser Pflanzen enthält einen Schatz an Informationen zu ihrer Geschichte und der Magie, die sie an den Weltenbaum bindet. Indem wir diese Blüten studieren, können wir die Herkunft jeder Pflanze besser verstehen.\n\nSammelt vorsichtig abgefallene Blüten auf und bringt sie mir.", sourceObjective = "Sammelt 3 Traumsaatblüten.", progress = "Habt Ihr die drei Blüten gesammelt?", completion = "Ihr habt gute Arbeit geleistet. Das wird Euch helfen, andere Pflanzenspezies von Samen wiederzubeleben, die Ihr findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[78172] = { id = 78172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvolle Samen", description = "<Sylvia Flüsterblüte könnte sich für diese geheimnisvollen Samen interessieren.>", sourceObjective = "Bringt die Samen zu Sylvia Flüsterblüte im Wildlingsgarten.\n\nBereitgestellter Gegenstand:", completion = "Diese Samen enthalten die Antworten, das Vermächtnis der fremdartigen Flora zu entschlüsseln, die im Feuer verloren ging, das Teldrassil verschlungen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[78177] = { id = 78177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Gilneas", description = "Die Zeit ist gekommen, um mein Königreich zurückzuerobern, Champion. Die Verlassenen haben dem Land wie versprochen den Rücken gekehrt.\n\nLeider haben die Kämpfer des Scharlachroten Kreuzzugs ihren Abzug ausgenutzt und die Stadt zu ihrer eigenen Festung auserkoren. Wir werden sie alle vertreiben.\n\nHelft mir dabei, Gilneas zurückzuerobern.", sourceObjective = "Reist nach Kielwasser in den Ruinen von Gilneas.", progress = "Gilneas wird wieder uns gehören.", completion = "Tja, offenbar liegt die Verantwortung nun in meinen Händen.\n\nEtwas unerwartet, aber nicht ungelegen.\n\nAlso gut. Lasst es uns angehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78178] = { id = 78178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Gilneas", description = "{name}, wir haben von einer baldigen Offensive in Gilneas erfahren.\n\nWir haben mit der Allianz zusammengearbeitet, um Gilneas wieder den Gilneern zu übergeben. Leider hat sich der Scharlachrote Kreuzzug in der Stadt einquartiert.\n\nWir wollen Unterstützung dabei leisten, die Scharlachroten auszurotten, damit die Gilneer ihr Land zurückbekommen.\n\nLilian und ich bitten Euch, uns bei dieser Operation zur Seite zu stehen.", sourceObjective = "Reist nach Gilneas in den Östlichen Königreichen und helft dabei, die Stadt wieder für die Gilneer einzunehmen.", progress = "Danke, dass Ihr zu Hilfe geeilt seid, {name}.", completion = "Hm.\n\nIch hatte nicht erwartet, das Kommando zu erhalten.\n\nNun gut. Auf in die Schlacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78180] = { id = 78180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Kreuzzug aus Rot", description = "Calia wird die Armee der Verlassenen zu einem Ablenkungsangriff in den Norden führen.\n\nIch möchte, dass Ihr Euch mit Lilian und mir in der Stadt trefft. Dort gibt es einen geheimen Tunnel, durch den wir in den Süden gelangen. Von dort aus können wir das Südtor öffnen und unsere Truppen hineinlassen, während die Scharlachroten durch Calias Truppen abgelenkt sind.\n\nEine Gruppe des Scharlachroten Kreuzzugs treibt sich derzeit am Eingang des Geheimtunnels herum. Könntet Ihr sie ausschalten?", sourceObjective = "Tötet 10 Mitglieder des Scharlachroten Kreuzzugs in Aderics Ruhestätte.", completion = "Der erste Schlag gegen den Scharlachroten Kreuzzug ist gelungen, dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[78181] = { id = 78181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aderics Retoure", description = "Die Späher berichten, dass der Scharlachrote Kreuzzug an Aderics Ruhestätte insbesondere von einer bestimmten Person dazu ermutigt wird, sich an den Gräbern meiner Leute zu schaffen zu machen.\n\nZu viele Gilneer haben ihr Leben gelassen, um dieses Land zu verteidigen. Ich werde nicht zulassen, dass ihr Opfer auf diese Weise... geschändet wird!\n\nSchaltet ihre Anführerin aus und übermittelt ihnen eine Botschaft, die sie so schnell nicht vergessen werden.", sourceObjective = "Tötet Konsekratorin Hennas in Aderics Ruhestätte.", progress = "Ist sie tot, {name}?", completion = "Ist es vollbracht? Gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[78182] = { id = 78182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kniehoch", description = "Tess und Voss warten am Ende des Tunnels auf Euch. Sobald Ihr drei dort angekommen seid, werdet Ihr das Südtor von innen öffnen und unsere Truppen in die Stadt lassen.\n\nFolgt dem Tunnel, um sie zu treffen. Nehmt diese Fackel, denn der Weg ist mit Ungeziefer verseucht.\n\nIch bereite unsere Truppen darauf vor, das Tor zu stürmen, sobald es offen ist.", sourceObjective = "Bahnt Euch den Weg durch den geheimen Tunnel in Aderics Ruhestätte nach Gilneas.", completion = "{name} Ihr kommt gerade recht.\n\nSeid Ihr bereit für die nächste Phase unseres Angriffs?", sourceObjectiveStatus = "unverified-source-field" }
quests[78183] = { id = 78183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrotes Blut", description = "Sie scheinen die Stadt mit ihren erfahrensten Kräften besetzt zu haben. Keine Sorge, ich habe reichlich Erfahrung darin, sie auszuschalten... persönlich.\n\nWir werden sie einen nach dem anderen dezimieren.", sourceObjective = "Tötet 12 Mitglieder des Scharlachroten Kreuzzugs.", completion = "Sie sind alle schon über den Punkt hinaus, als dass man vernünftig mit ihnen reden könnte. So eine Verschwendung von Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78184] = { id = 78184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knall und Rauch", description = "Das Tor zu öffnen, ist schön und gut, aber wir müssen als Erstes einen Weg für unsere Truppen frei machen. Unsere Späher haben berichtet, dass der Kreuzzug Sprengstoff im Gebiet deponiert hat.\n\nIch bin sicher, es macht ihnen nichts aus, wenn wir uns etwas borgen, meint Ihr nicht?", sourceObjective = "Sammelt 8 Ladungen Scharlachroten Sprengstoff.", completion = "Kein Grund, feinen Sprengstoff zu vergeuden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78185] = { id = 78185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunde des Krieges", description = "Ich denke, wir hatten allein genug Spaß, oder?\n\nDie Scharlachroten, die nahe der Stadtkapelle stationiert sind, scheinen die Elitetruppe zu sein. Ich denke, dort werden wir auch ihren Anführer finden, aber allein dort hinzugehen, ist unnötig riskant.\n\nEs wird Zeit, die wahre Macht von Gilneas zu zeigen und unsere Stadt zurückzuerobern. Meine Truppen sind bereit zum Sturmangriff!", sourceObjective = "Öffnet die Stadttore von Gilneas.", progress = "Mein Volk steht bereit.", completion = "Jetzt beginnt der eigentliche Kampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[78186] = { id = 78186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kreuzzug zerschmettern", description = "Die schlagkräftigsten Mitglieder des Scharlachroten Kreuzzugs werden das Nest ihres Anführers verteidigen, {name}. Und da komme ich ins Spiel.\n\nEs geht doch nichts über eine kleine Ablenkung, um einen Feind schnell auszuschalten. Lasst mich einfach wissen, wo und wann ich zuschlagen soll.", sourceObjective = "Tötet 12 Mitglieder des Scharlachroten Kreuzzugs im Hof der Stadtkapelle von Gilneas.", completion = "Gut. Meine Truppen schalten den Rest von ihnen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[78187] = { id = 78187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artillerieanzünder", description = "Die Kapelle scheint ihre Basis zu sein, und sie wird gut verteidigt. Sie haben im ganzen Hof mehrere Verteidigungsanlagen errichtet. Die Belagerung würde unseren Truppen leichter fallen, wenn wir einige von ihnen aus dem Weg schaffen könnten.\n\nErinnert Ihr Euch an den Sprengstoff, den wir eingesammelt haben? Den könnten sie jetzt gut gebrauchen.", sourceObjective = "Platziert 6 Sprengladungen.", completion = "Das sollte unseren Streitkräften eine Atempause verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78188] = { id = 78188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtes Feuer, gerechte Wut", description = "Zwischen uns und unserer Stadt steht nur noch eine Person. Macht Euch bereit, denn das wird ein harter Kampf.", sourceObjective = "Tötet die Anführerin des Scharlachroten Kreuzzugs.", progress = "Ist sie tot?", completion = "Wir haben es geschafft. Der Wiederaufbau wird natürlich einige Zeit dauern, aber Gilneas gehört wieder uns!\n\nIch kann es kaum glauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78189] = { id = 78189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neuer Morgen bricht an", description = "Vieles hat sich verändert, seit wir diese Stadt verlassen mussten. Sowohl dieses Land als auch unser Volk.\n\nWerdet <Zeuge/Zeugin>, {name}, der Zukunft von Gilneas.", sourceObjective = "Lauscht Genn Graumähnes Gespräch mit Tess.", completion = "Ich... Ich weiß nicht, was ich sagen soll. Ich danke Euch, {name}. Für alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[78190] = { id = 78190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir zurückließen", description = "Er hat... mir einfach das Königreich überlassen.\n\nMir!\n\nDas muss ich erstmal verarbeiten. Aber... hört zu, {name}. Mein Vater ist ein starker Mann, aber manchmal versteift er sich so auf etwas, dass ich Angst habe, dass er noch zerbricht. Ich will ihn nicht verhätscheln, aber könntet Ihr ihm folgen und sicherstellen, dass er wohlauf ist? Es würde das Herz seiner Tochter sehr beruhigen...\n\nDas Herz einer Königin.", sourceObjective = "Folgt König Graumähne und behaltet ihn im Auge.", completion = "Tess hat Euch geschickt, nicht wahr? Dieses Mädel... Sie ist clever, entschlossen und liebt so inbrünstig, wie sie kämpft. Deshalb trägt sie nun die Verantwortung.\n\nSorgt Euch nicht um mich, {name}. Ich habe in dieser Welt noch eine Rolle zu spielen. Die Allianz braucht weiter meine Expertise. Und jetzt, da ich Gilneas in guten Händen weiß, kann ich mich voll und ganz dieser Aufgabe widmen. Dennoch danke ich Euch für Eure Sorge.\n\nIch weiß zu schätzen, was Ihr im Laufe der Jahre für mein Königreich getan habt. Ihr seid ein eindrucksvolles Beispiel der Fähigkeiten, die ich selbst noch meistern möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[78203] = { id = 78203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superblüte" }
quests[78206] = { id = 78206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdfülle", description = "Es gibt so viele weitere Arten, die Ihr finden und untersuchen könnt. Wenn Ihr den Traum erforscht, werdet Ihr weitere Samen finden, die als Traumsaat bekannt sind. Bitte pflegt sie, um unsere Studien fortzusetzen, und genießt die Früchte, die sie mit Euch teilen werden!\n\nTraumsaat findet man überall, aber viele werden von mächtigen Kreaturen überall im Traum gesammelt.\n\nIhr solltet zudem ein Auge auf die Lebensenergie haben, die wir Smaragdraserei nennen. Sie ist eine Quelle vieler smaragdgrüner Tautropfen, die bei der Aufzucht der Traumsaat behilflich sein können.", sourceObjective = "Nehmt an der Smaragdraserei teil, um smaragdgrüne Tautropfen zu verdienen, und steuert eine Traumsaat bei, um neues Wachstum anzuregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78215] = { id = 78215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Gefahr verwurzelt" }
quests[78226] = { id = 78226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine äußerst interessante Einladung", description = "Wir haben eine Einladung erhalten. Oder besser gesagt, habt Ihr das, {name}.\n\nMan bittet Euch, Euch mit dem Wesir zu treffen. Der Name bringt selbst die wohlhabendsten und mächtigsten Gestalten in der Stadt der Fäden zum Schaudern.\n\nWenn wir ihn als Verbündeten gewinnen, könnte das unseren Sieg über Ansureks grässlichen, kleinen Schatten endgültig besiegeln.\n\nIhr werdet ihn im Bau treffen. Benutzt den Pheromonspender hier in meinem Nest, um Euch ausreichend zu tarnen und sicher hineinzugelangen.", sourceObjective = "Trefft Euch mit dem \"Wesir\" im Bau in Azj-Kahets Stadt der Fäden.", completion = "Es überrascht mich ein wenig, dass es Euch gelungen ist, Verbündete unter den Kaheti zu finden, {name}.\n\nUnd ja, ich bin gesund und munter.\n\n\n\nIhr seid hoffentlich nicht allzu schockiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[78228] = { id = 78228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stadt der vielen Beine", description = "Ich habe diese \"Einladungen\" an Euch und Alleria geschickt. Ich hätte das Schwert meines Vaters darauf verwettet, dass Ihr Euch eine derart einmalige Gelegenheit nicht entgehen lassen würdet. Das ist es, was Euch von uns allen unterscheidet. Alleria hingegen ...\n\nEgal. Sie ist so vorsichtig, wie sie selbstbewusst ist. Ich schätze, ich habe auf Letzteres gehofft, doch es ist Ersteres, das sie am Leben gehalten hat.\n\nVielleicht wird sie später noch zu uns stoßen. Doch fürs Erste ist es an der Zeit, dass Ihr und meine neue Bekanntschaft Euch endlich richtig kennenlernt.", sourceObjective = "Erzählt dem Wesir vom Plan der Weberin und tragt Pheromone auf, um Zutritt zum Umbralbasar zu erhalten.", progress = "Trotz seiner jungen Jahre scheint Meister Anduin ja geradezu vor Lebenserfahrung zu strotzen. Das sieht man für gewöhnlich nur bei jenen, die in ihrem Leben schon weit gereist sind.\n\nBeeindruckend. Zumindest aus der Sicht eines einfachen Kaheti.", completion = "Was für ein Auftritt. Sollte ich bei der nächsten Kabinettssitzung auch mal versuchen.\n\n<Nizrek gibt ein Husten von sich, das genauso gut ein Lachen sein könnte.>\n\nVielleicht sollten wir ihnen etwas Privatsphäre geben. Würdet Ihr Euch ein kleines Anliegen von mir anhören, während sie beschäftigt sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[78231] = { id = 78231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie eine Spinne an der Wand", description = "Alleria einzuladen, war ein Risiko... doch selbst jetzt bin ich der Meinung, dass es dieses Risiko wert war. Ich weiß es.\n\nIch werde selbst mit ihr sprechen. Ich möchte, dass Ihr Euch in der Zwischenzeit nach oben in die Stadt begebt. Die Pheromone, die Nizrek Euch gegeben hat, werden Euch Zutritt zum Umbralbasar gewähren. Beobachtet die Händler, belauscht die Gespräche, kauft ihre Waren.\n\nDiese Stadt ist so geschäftig wie Sturmwind. Und ihre Bewohner haben es genauso verdient, vom Missbrauch erlöst zu werden, wie unsere. Seht selbst, wie ähnlich wir uns doch alle sind.", sourceObjective = "Erkundet den Umbralbasar.", completion = "Ein lebhaftes Volk, wie alle anderen, die wir gemeinsam über die Jahrzehnte kennenlernen durften.\n\nSie verdienen denselben Frieden und Schutz, nach dem auch wir für unsere Völker streben.\n\nLasst uns schwören, dass wir immer gegen die Quelle des Unfriedens kämpfen werden, wenn wir dazu gezwungen werden, nie gegen die Opfer davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[78232] = { id = 78232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manipulation der Manipulierten", description = "Wir haben Euch hergerufen, weil heute \"Tag des Aufstiegs\" ist. Königin Ansurek ließ sich dazu herab, ihn zum Feiertag für unsere neugewonnene, leerenerfüllte Evolution auszurufen. Unser \"Aufstieg\". Ich hoffe, mein sarkastischer Unterton ist Euch aufgefallen.\n\nWährend die Straßen mit allerlei Feierlichkeiten und vergnügten Bürgern gefüllt sind, werden die Schattenwerfer, die über den ganzen Basar verteilt sind, die Luft mit Ansureks niederträchtiger Propaganda verpesten.\n\nNehmt meine Erfindung und benutzt sie, um sie zu manipulieren, damit sie... erhellendere Informationen verbreiten.", sourceObjective = "Manipuliert 3 Schattenwerfer.", completion = "Ja. Der Wesir hat mich darum gebeten, in den anderen Bezirken genau das Gleiche zu tun.\n\nZugegeben, mein Vertrauen gegenüber Anduins neuem Verbündeten ist leicht gestiegen. Zwar nicht mehr als um die Länge eines kleinen Fingers, aber selbst das ist mehr, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[78233] = { id = 78233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geschenk der Weberin", description = "Eine kleine Weberatte hat mir erzählt, dass sich im Norden eine spannende Reihe an Ereignissen abspielt. Anscheinend folgt dort ein überraschend zufälliger Fehlschlag auf den anderen, was die militärischen Bemühungen dort stört.\n\nIch will wissen, wer dafür verantwortlich ist. Geht der Sache auf den Grund. Vielleicht kann Euer seltsames Paar Augen eventuelle Verbündete erspähen.\n\nEinige unserer kleinen Freunde befinden sich unter den Ausreißern, die den Zorn von \"Zev'kall\" auf sich ziehen. Holt sie ein. Sagt ihnen, dass die Weberin ihnen... Grüße überbringt.", sourceObjective = "Findet die Freunde, von deren Existenz Ihr durch das Geschenk der Weberin erfahren habt.", completion = "Wir dachten, wir wären gut versteckt.\n\nOffensichtlich nicht so gut, wie wir gehofft hatten, aber ich bin dennoch froh, Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78234] = { id = 78234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Gewalt durch die Mitte", description = "Auch ohne den General wird die Flucht kein Kinderspiel. Es wimmelt hier nur so vor Feinden.\n\nIch weiß, dass ich es gut verberge, aber ich bin nicht gerade in bester Verfassung. Ich bin mir nicht sicher, ob ich Euch eine große Hilfe sein werde.\n\nIhr müsst den Weg für uns freikämpfen.", sourceObjective = "Tötet 8 Streitkräfte der Kaheti in Rak-Zakaz.", completion = "Zu meiner Verteidigung möchte ich sagen, dass sie mir meine Waffen abgenommen haben. Und vergiftet haben sie mich auch. Sieht das für Euch eigentlich irgendwie entzündet aus?\n\nJedenfalls hätte ich Euch auf jeden Fall geholfen, wenn all das nicht wäre. Darauf habt Ihr mein Wort.", sourceObjectiveStatus = "unverified-source-field" }
quests[78236] = { id = 78236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartgesottener Nachzügler", description = "Wenn wir jemanden zurückgelassen haben, müssen wir etwas unternehmen.\n\nIch sage es nur ungern, aber die Leute hier brauchen jemanden, der auf sie aufpasst. Also muss ich hierbleiben.\n\nSucht nach dem Nachzügler und wenn Ihr schon dabei seid, schaut Euch auch ruhig hinter den feindlichen Linien um. Vielleicht findet Ihr ja irgendwas Nützliches.", sourceObjective = "Rettet den Nachzügler in Rak-Zakaz.", completion = "Ich hatte definitiv alles unter Kontrolle.\n\n<Flynn zuckt zusammen.>\n\nDoch... ich gebe zu, dass dieses Gift meine ansonsten blitzschnellen Reflexe verlangsamt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78237] = { id = 78237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Lieferung!", description = "Hm. Dieser Anub'azal hat Befehle erteilt, die zur Flucht der Gefangenen geführt haben. Zev'kall hier schien nicht besonders erfreut darüber.\n\nWas haltet Ihr davon: Ihr schleicht Euch in die Belagerungsfeste und schließt Freundschaft mit Anub'azal. Ganz leicht.\n\nMir ist aufgefallen, dass eine Menge Fracht übergesetzt wird. Es würde bestimmt niemandem auffallen, wenn wir den Inhalt einer einzigen Kiste austauschen.\n\nIn der Zwischenzeit teile ich der Weberin unsere Erkenntnisse mit. Ich würde Euch nur zu gern begleiten, aber ich möchte kein weiteres Attentat auf mich provozieren.", sourceObjective = "Versteckt Euch in einer Kiste, um in die Belagerungsfeste transportiert zu werden.", completion = "Eine interessante \"Lieferung\" seid Ihr mir.\n\nIch werde Verwendung für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78244] = { id = 78244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gastfreundschaft der Kaheti", description = "Auf dieser Bühne ganz da hinten wird Ansurek ihre Rede für den Tag des Aufstiegs halten.\n\nIhr, Alleria und ich werden uns an die Spitze eines der Türme in der Nähe begeben und beobachten. Wenn wir ihre eigenen Bürger gegen sie aufbringen wollen, müssen wir so viel Wissen über ihre Taktiken sammeln, wie wir können.\n\nIch habe es Alleria bereits erzählt, doch wir dürfen auf keinen Fall auffallen. Für den Fall, dass wir in Schwierigkeiten geraten, hat der Wesir eine Reihe Fluchtflieger am Rand des Baus aufgestellt, wo wir uns das erste Mal begegnet sind.", sourceObjective = "Sprecht mit Anduin, wenn Ihr bereit seid, die Ansprache zum Tag des Aufstiegs zu beobachten und die Stadt danach unauffällig zu verlassen.", completion = "Wir haben es geschafft. Nicht notwendigerweise so klammheimlich, wie ich gehofft hatte, aber zumindest sind wir am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78248] = { id = 78248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was wir noch haben", description = "Ich bin vorbereitet in die Stadt gegangen, darauf vorbereitet, diesen Krieg zu beenden, auch wenn das mein Ende bedeutet hätte.\n\nDoch ich bin am Leben. Genau wie Ihr. Genau wie Anduin. Wir haben neue Verbündete und einen neuen Weg vor uns. In diesem Moment erkenne ich, dass meine Wahrnehmung womöglich von meiner Schuld vernebelt wurde.\n\nEin Teil von mir hat das Gefühl, als wären dies Anduins Worte und nicht meine. Vielleicht färbt er auf mich ab.\n\nLasst uns ins Nest Eurer Weberin zurückkehren. Ich will, dass Eure und Anduins Bemühungen, diese Leute zu retten, genauso von Erfolg gekrönt sein werden wie die unseren.", sourceObjective = "Kehrt zum Nest der Weberin zurück.", progress = "Ich meine, mich zu erinnern, Euch nahegelegt zu haben, in der Stadt nicht aufzufallen, oder irre ich mich?", completion = "Wie oft wurde ich schon von meinem Verdacht abgebracht, dass \"der Wesir\" Exekutor Nizreks wahre Identität ist? Vielleicht bin ich nicht mehr so gut, wie ich mal war. Ich! Eine Meisterin der Spionage.\n\nHa, es ist wohl eher der Fall, dass er einfach viel besser ist, als ich ihm zugestehen will.\n\nDie Vorstellung, dass jemandes Geschick für List und Trickserei meins übertrifft, bereitet mir Unbehagen. Wir sollten ein gutes Team abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78249] = { id = 78249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wichtige Schachfiguren", description = "Zev'kall hat vor Kurzem seine eigenen treuen Lakaien in Schlüsselpositionen um die Belagerungsfeste herum stationiert. Sie zu töten, wird Ersatzleute erforderlich machen, die neu ausgebildet werden müssen, was wiederum Chaos stiftet.\n\nAll das wird Zev'kall in Bedrängnis bringen. Kümmert Euch um alle drei.", sourceObjective = "Tötet Zev'kalls Lakaien im Auftrag von General Anub'azal.", completion = "Zev'kall weiß, dass ich involviert bin. Ich wollte, dass er es weiß. Doch er kann nichts sagen, da er nicht in der Lage ist, seine eigenen Pheromonmarker zu erzeugen. Ich habe für seine Bedürfnisse bisher meine eigenen verwendet.\n\nGäbe er zu, dass er dazu nicht imstande ist, würden alle seine Autorität hinterfragen... und erst recht seinen Status als Neruber.\n\nDas wäre ein ziemlicher Skandal.", sourceObjectiveStatus = "unverified-source-field" }
quests[78250] = { id = 78250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingeständnis des Generals", description = "Es reicht nicht aus, Zev'kall nur in Verlegenheit zu bringen. Er muss gedemütigt werden. Ich habe bereits ein paar Informationen, aber ich brauche noch mehr.\n\nEr bewahrt militärische Protokolle in einem Raum auf, der zu klein ist, als dass ich ihn betreten könnte. Findet heraus, welche Informationen er versteckt. Ich bin mir sicher, dass sich dort Dokumente befinden, mit denen man ihn erpressen kann.", sourceObjective = "Findet brauchbares Erpressungsmaterial für den General.", progress = "Darin sollte sich doch etwas Brauchbares finden.", completion = "Mal sehen!\n\nDas... taugt nicht zur Erpressung, aber es ist etwas viel Schlimmeres.", sourceObjectiveStatus = "unverified-source-field" }
quests[78251] = { id = 78251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verzweifelten von Dalaran", description = "Ich traue diesem großen Insekt nicht über den Weg. Er ließ mich eine halbe Ewigkeit dort liegen, ohne etwas zu sagen!\n\nDoch wenn er uns Zugang zur Belagerungsfeste verschaffen will, sollten wir davon Gebrauch machen. Ich habe gesehen, wie Leute in andere Bereiche der Basis verschleppt wurden. Ich glaube nicht, dass sie sie fressen. Es sieht eher danach aus, als würden sie sie irgendwo hinbringen.\n\nTreiben wir sie zu einem Gefangenenkonvoi zusammen und bringen sie nach draußen. Ihr findet mich außerhalb der Feste!", sourceObjective = "Befreit Gefangene für den falschen Gefangenenkonvoi.", completion = "Wow... Das sind eine MENGE Leute.\n\nDoch sie sind alle in einem sehr jämmerlichen Zustand. Glücklicherweise ist das die beste Voraussetzung, um meine Idee zu verkaufen.\n\nDas könnte funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[78254] = { id = 78254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlener Einfluss", description = "Diese Protokolle von Zev'kall... Er opfert zahllose Neruber. Wirft ihre Leben weg wie eine tollwütige Heuschrecke.\n\nWir müssen handeln. Wie ich schon sagte: Zev'kall erzeugt aufgrund dieses \"Aufstiegs\" keine eigenen Pheromonmarker mehr. Er ist gezwungen, meine zu verwenden. Sein Alchemist versucht, welche für ihn zu brauen... aber sobald das geschieht, was ist dann mit mir?\n\nNehmt diese falschen Pheromone und schmuggelt sie aus der Belagerungsfeste. Stellt Zev'kall bloß, benutzt sie... Ihr seid doch einfallsreich, oder nicht? Stiftet einfach etwas Chaos.", sourceObjective = "Stehlt die Pheromone und bereitet einen heimlichen Transport aus der Belagerungsfeste vor.", progress = "Um was hat Euch der General gebeten?", completion = "Sie rausschmuggeln? Hmm.\n\nIch wette, die können wir noch später gebrauchen, aber... wenn wir sie schon benutzen, dann für unsere Flucht.\n\nDoch hoffentlich kommt es erst gar nicht dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[78255] = { id = 78255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur nicht auffallen", description = "Es ist an der Zeit, mit den Gefangenen und den Pheromonen von hier zu verschwinden. Ich habe einige überzeugende Ketten gefunden, da wir eine so große Gruppe sind. Solange keiner aus der Rolle fällt, haben wir gute Chancen.\n\nWir haben nur den Markierungsduftschleim von General Anub'azal für uns beide, also werden wir die Drohnen sein. Ihr übernehmt das Reden, während ich auf den Wagen achte. Hoffentlich funktioniert das.\n\nFührt uns durch das Tor, {name}!", sourceObjective = "Helft dem Konvoi, die Belagerungsfeste zu verlassen, indem Ihr mit der Torwächterin sprecht.", completion = "Machen wir eine kleine Verschnaufpause. Wir haben doch niemanden verloren, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[78256] = { id = 78256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Meinung des Generals", description = "Wir hatten Glück. General Anub'azal ist so daran interessiert, Zev'kall zu sabotieren, dass in diesem Fall der Feind unseres Feindes tatsächlich unser Freund war.\n\nDas könnte hier zum Thema werden: Spinnen, die versuchen, uns gegeneinander auszuspielen. Na schön.\n\nIhr wollt die Pheromone sicherlich irgendwo sinnvoll einsetzen, oder? Macht das. Ich bringe die Leute hier in Sicherheit.", sourceObjective = "Bringt Zev'kalls Pheromone zu jemandem, der damit etwas anfangen kann.", progress = "Was habt Ihr für mich?", completion = "Was für ein herrliches Geschenk!\n\nGeneral Anub'azal könnte ein hervorragender Verbündeter sein. Ich bin mit Eurer Arbeit zufrieden, Leckerbissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78262] = { id = 78262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es beginnt mit einem Stein", description = "In diesen Landen gibt es so viele Geheimnisse. Und noch mehr Macht!\n\nUnd Ihr... Wir beide wissen, dass Ihr gerne Geheimnisse lüftet und wunderbare Ausrüstung sammelt. Und wenn Ihr bereit seid, die Macht der Ausrüstung freizusetzen, die Ihr in diesen neuen Landen findet, sucht Cuzolth und mich auf. Wir führen Experimente durch und werden Eure Ausrüstung aufwerten können, wenn Ihr wieder zurück seid.\n\nBitte bringt mir Flugsteine und einen neuen Gegenstand, damit ich Euch zeigen kann, wie diese Aufwertungen funktionieren.", sourceObjective = "Besorgt 50 Flugsteine, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge meistert, Weltquests abschließt oder Schätze plündert. Sprecht danach mit Cuzolth und wertet einen Ausrüstungsgegenstand aus Saison 3 unter Einsatz von Flugsteinen auf.", progress = "Könnt Ihr diese Macht spüren? Die Vorfreude, wenn man weiß, dass man jetzt noch gewagtere Abenteuer erleben kann?", completion = "Seht Euch nur dieses Schimmern und Glitzern an!\n\nBitte nehmt diese Geschenke.", sourceObjectiveStatus = "unverified-source-field" }
quests[78271] = { id = 78271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappentraum", description = "Ihr habt die Grundlagen erlernt. Jetzt könnt Ihr ganz leicht Ausrüstung der unteren Stufen aufwerten.\n\nEher früher als später werdet Ihr jedoch bessere Ausrüstung finden, die Ihr nur mithilfe von verschiedenen Arten von Traumwappen aufwerten könnt. Ähnlich wie bei den Flugsteinen erwerbt Ihr diese Wappen durch zahlreiche unterschiedliche Aktivitäten. Traumwappen lassen sich in vier Ränge unterteilen, und je gefährlicher die Aufgabe, desto höher der Rang der Wappen!\n\nGeht und erledigt Aufgaben, besiegt furchterregende Feinde, findet Schätze und bringt mir ein paar Handvoll Traumwappen des Welpen.", sourceObjective = "Besorgt 15 Traumwappen des Welpen, indem Ihr einzigartige Kreaturen besiegt, Dungeons und Schlachtzüge bezwingt, Weltquests abschließt oder Schätze plündert. Sprecht danach mit Vaskarn.", completion = "Ja, ja! Diese Wappen bergen große Macht. Und Ihr nun auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[78274] = { id = 78274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quakende Maßnahmen", description = "Und auf ein Neues. Wärt Ihr so gut und verjagt wieder diese Enten? Ich muss hierbleiben und ein Auge auf mein goldenes Ei haben.", sourceObjective = "Verschreckt 10 Enten mithilfe des Horns des Hupens.", progress = "Zeigt den Enten, wer hier der Boss ist!", completion = "Das wird ihnen eine Lehre sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[78289] = { id = 78289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Bummelgau", description = "Aus Bummelgau, am Fuß der Donnerkopfspitze, erreichen uns beunruhigende Nachrichten. \n\nIch kann den Ort ja nicht ausstehen. Ständig regnet und rumpelt es.\n\nAber Krähenhüterin Lufsela dachte, dass es Sinn ergeben würde, sich dort umzusehen, schon alleine, weil die Vögel das Moos lieben, für das der Ort bekannt ist. Sie ist allerdings noch grün hinter den Ohren und könnte vielleicht ein wenig Hilfe brauchen.", sourceObjective = "Trefft Lufsela in Bummelgau.", completion = "Otwin hat Euch geschickt? Er vermisst vermutlich meine Hilfe beim Ausfegen der Krähenhorste. Aber irgendwas stimmt hier nicht so ganz in Bummelgau.\n\nEigentlich sollte über unseren Köpfen ein Sturm toben. Man kann ihn von Dornogal aus sehen, solange ich zurückdenken kann. Ich fürchte, dass die örtliche Mooswollenproduktion ohne diesen Sturm in echten Schwierigkeiten sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[78290] = { id = 78290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Schafe", description = "Das energiegeladene Moos, das diese Herden produzieren, ist ein Leckerbissen für die Sturmkrähen. Aber durch den ausbleibenden Sturm sind die Widder lethargisch und angreifbar geworden und sie haben ihre Produktion eingestellt.\n\nWir können vielleicht keinen Sturm herbeizaubern, aber wir könnten den Mooswollen einen motivierenden Schock verpassen. Versucht doch mal, einen Leitstein zu finden, der eine Ladung aufnehmen kann. Bringt ihn dann her zu Shraubendre, damit sie ihn aufladen kann.", sourceObjective = "Benutzt einen energetisierten Leitstein, um 8 lethargische Mooswollen in der Nähe von Bummelgau aufzuscheuchen.", progress = "Der Leitstein sollte gerade genug Ladung enthalten, um den Mooswollen die Motivation zu verleihen, die sie brauchen, um zu ihren Pferchen zurückzukehren. Es wird ihnen nicht wehtun.", completion = "Die Mooswollen scheinen über etwas mehr Elan zu verfügen. Hoffentlich werden sie schon bald die Produktion wieder aufnehmen. Dafür muss allerdings der Sturm zurückkommen.\n\nViehzüchter Stenspor glaubt zu wissen, warum der Sturm bisher ausbleibt. Er behauptet, dass zwei legendäre Widderbrüder den Sturm einmal im Jahr mit Energie versorgen. In diesem Jahr aus irgendeinem Grund allerdings nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78291] = { id = 78291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtige Raubtiere", description = "Über der Donnerkopfspitze tobt normalerweise ein beständiger Sturm, aus dem die örtlichen Mooswollen ihre Energie ziehen. Ohne ihn wirken die armen Schafe teilnahmslos und halbtot. Das macht sie zu leichter Beute für Raubtiere.\n\nUm die Moosproduktion wieder anzukurbeln, müssen wir dahinter kommen, warum der Sturm ausbleibt. Aber zuerst müssen wir diese Raubtiere zurücktreiben, bevor sie sich über die Mooswollen hermachen können.", sourceObjective = "Merzt 10 Raubtiere in der Umgebung von Bummelgau aus.", completion = "Das sollte den Viehzüchtern und ihren Herden etwas Zeit verschaffen, während wir herausfinden, was es mit dem ausbleibenden Sturm auf sich hat. Ohne Sturm kein Moos, was wiederum zu griesgrämigen Sturmkrähen führt.\n\nDie Einheimischen behaupten, der Sturm würde geboren, wenn zwei legendäre Widder oberhalb der Donnerkopfspitze ihre Kräfte messen. Sie glauben, dass einer der beiden verschwunden wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[78292] = { id = 78292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorener Sturmfürst", description = "Hört gut zu, Fremdling. Einmal im Jahr überquert der große Widder Durzan, der Fürst des Südlichen Sturms, die Insel, um sich mit seinem Bruder Belzt auf der Donnerkopfspitze zu treffen. Das Aufeinandertreffen ihrer Hörner kündigt den Sturm an und bringt Wohlstand für ein weiteres Jahr.\n\nAber irgendwas stimmt nicht. Durzan ist nicht gekommen und die Himmel haben sich gelichtet. Es mag sein, dass die Sturmreiter nicht daran glauben, aber ich habe schon verrücktere Dinge gesehen.\n\nFragt herum, wenn Ihr noch Zweifel habt. Aber bitte helft uns, Durzan zu finden.", sourceObjective = "Findet Durzan in der Nähe von Bummelgau.", progress = "Lasst uns beten, dass Durzan noch unter uns weilt. Wenn sein Bruder ihn nicht auf der Spitze antrifft, ist der Sturm und mit ihm unser ganzer Lebensunterhalt verloren.", completion = "Ihr habt ihn gefunden! Aber warum ist er nicht zu dem Berg gegangen? Und warum wirkt er so niedergeschlagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[78293] = { id = 78293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Moos, mehr los", description = "Ihr sagt, dass er in den Fängen der Neruber war? Ich verstehe nicht, was sie mit dem alten Durzan vorhatten, aber er wirkt, als hätte diese Marter ihn ganz schön mitgenommen. Das ist kein Zustand, in dem er seinen Bruder Belzt auf dem Berg herausfordern kann.\n\nDas Moos, das von unseren Herden gewonnen wird, verleiht den Sturmkrähen einen Energieschub, vielleicht kann Durzan daraus den gleichen Nutzen ziehen. Sammelt einen Scheffel davon und bereitet eine Opfergabe vor.\n\nUnd wenn die Mooswollen störrisch werden, dann stellt sicher, dass sie sich wieder einkriegen.", sourceObjective = "Sammelt Moos von den Bummelgaumooswollen und füttert Durzan damit.", progress = "Dieses Moos fängt die Macht des Sturms ein und speichert sie. Das sollte Durzan den Schub verleihen, den er braucht, um auf den Berg raufzukommen.", completion = "Das scheint funktioniert zu haben. Ich glaube, er ist bereit, zu seinem Bruder auf der Donnerkopfspitze zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[78294] = { id = 78294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donnerkopftreffen", description = "Durzan wirkt wieder putzmunter. Dieses Moos hat es wirklich in sich.\n\nIch habe den Eindruck, dass er bereit ist, loszuziehen. Ich wünschte bloß, wir hätten mehr Zeit. Ich habe noch so viele Fragen. Aber die wichtigste dieser Fragen wird beantwortet, sobald er die Spitze erreicht.\n\nWir sollten ihn nicht alleine dort hinauf schicken. Aber ich denke, er vertraut Euch, ihn zu begleiten.", sourceObjective = "Begleitet Durzan zu Belzt auf der Donnerkopfspitze.", progress = "Wir werden von hier aus zusehen. Ich hoffe wirklich, dass Belzt dort oben auf ihn wartet.", completion = "Die Legenden waren wahr. Die Stürme, die Krähen und diese Widder. Sie sind alle miteinander verbunden.\n\nEs gibt noch so viel, was ich lernen muss. Aber ich danke Euch, dass Ihr mir diesen Weg gewiesen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78301] = { id = 78301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halunkeneck-Heuler", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78302] = { id = 78302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halunkeneck-Heuler - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78303] = { id = 78303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halunkeneck-Heuler - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78319] = { id = 78319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Superblüte", description = "Amirdrassil wächst und braucht Nährstoffe. Der gute alte Fichtenkrone hat ein Ritual, um Leben um den Baum herum erblühen zu lassen, aber unsere Feinde haben Wind davon bekommen. Wir brauchen jede Hilfe, die wir kriegen können.\n\nWährend des Rituals zapft Fichtenkrone die Magie des Traumes an, um Traumfrüchte wachsen zu lassen. Wenn Ihr sie verzehrt, erlangt Ihr erstaunliche Kräfte. Es können immer nur einige wenige Exemplare dieser köstlichen Früchte erscheinen. Haltet die Augen nach ihnen auf!\n\nSeid so gut und helft uns aus, und der Traum wird Euch reich belohnen.", sourceObjective = "Nehmt an der Superblüte teil und verzehrt die Traumfrucht, die dabei erscheint.", progress = "Selbst jene unter uns, die am höchsten gewachsen sind, brauchen dann und wann etwas Hilfe bei den Wurzeln.", completion = "Ah, der frische Duft von Blumen liegt in der Luft!\n\nDanke, edler Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[78325] = { id = 78325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolchbucht-Durchrasen", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78326] = { id = 78326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolchbucht-Durchrasen - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78327] = { id = 78327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dolchbucht-Durchrasen - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78328] = { id = 78328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach herumstöbern", description = "Auf der Gala der Geschenke demonstrieren die vielen wunderbaren Kunsthandwerker, wie sie sorgfältig gearbeitete Geschenke für Euch und Eure Liebsten herstellen.\n\nIhr solltet Euch ansehen, was sie zu bieten haben, und mit den anderen Besuchern sprechen. Möglicherweise findet Ihr ja das perfekte Geschenk für jemanden, der Euch am Herzen liegt!", sourceObjective = "Besucht die Händler und Besucher auf der Gala der Geschenke.", completion = "Sind die Waren nicht alle fabelhaft? Ich bin ein bisschen neidisch auf dieses Talent. Und es fällt mir schwer, nicht alles, was sie gemacht haben, mitzunehmen!\n\nIst Euch etwas ins Auge gefallen?", sourceObjectiveStatus = "unverified-source-field" }
quests[78329] = { id = 78329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe liegt in der Luft", description = "Riecht mal an diesen Rosen! Meine Partnerin hat sie für mich bei der Gala der Geschenke besorgt.\n\nWollt Ihr Euch das selbst ansehen? Begebt Euch zu den Toren von Sturmwind. Es gibt Geschenke... und Essen, und Ihr solltet die Schokolade kosten, sie ist köstlich!", sourceObjective = "Besucht die Gala der Geschenke an den Toren von Sturmwind.", completion = "Willkommen auf der Gala der Geschenke!\n\nMöchtet Ihr mehr über meine Schokoladenspezialitäten erfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[78332] = { id = 78332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das riecht nach Ärger", description = "Ihr riecht diesen komischen Geruch auch? Riecht wie Rauch, billiges Duftwasser und alchemistischer Unfug. Wenn Ihr mich fragt, ich glaube, die Chemiemanufaktur Krone heckt irgendwas aus. Wollt Ihr mir helfen, der Sache auf den Grund zu gehen?\n\nTja, dann seht mal her! Sieht aus wie ein stinknormaler Köter, aber das ist O.D.I.E., das Olfaktorische Detektions- und Identifikations-Exemplar! Mit diesem kleinen Helfer können wir 10 km gegen den Wind erschnüffeln, was Krone im Schilde führt!\n\nSeid Ihr dabei? Ich könnte einen guten Partner brauchen, um das Rätsel zu lösen.", sourceObjective = "Nutzt O.D.I.E.s Fernsteuerung, um Hinweise in Sturmwind zu finden.", progress = "Klar, O.D.I.E. kann die Hinweise erschnüffeln, aber Ihr müsst sie schon zu einem Bild zusammenfügen.", completion = "Giftiges Parfüm? Rache dafür, dass sie aus der Stadt geworfen wurden?\n\nKlingt so, als würde Apotheker Hummel wieder irgendwas Finsteres auskochen. Aber tödliche Gifte? O weh, das könnte hässlich enden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78334] = { id = 78334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzwassersprudeln", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78335] = { id = 78335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzwassersprudeln - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78336] = { id = 78336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzwassersprudeln - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78337] = { id = 78337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unliebsames Geschenk", description = "Ich habe so den Verdacht, dass sich Spione der Chemiemanufaktur Krone unters Volk gemischt haben. Zum Glück weiß ich auch, dass Ihr wisst, dass O.D.I.E. hier weiß, wie wir ihnen auf die Geruchsspur kommen!\n\nAber wir brauchen ja niemanden zu belästigen, der einfach ein bisschen entspannen will, klar? Also haltet die Nase nur nach Chemikalien offen und stellt sicher, dass wir die richtigen Ziele treffen.", sourceObjective = "Tötet 8 Mitglieder von Chemiemanufaktur Krone in Sturmwind.", completion = "Herrje, {name}, Ihr mieft!\n\n\n\nSchlimmer noch! Ich miefe!\n\nNa, wenigstens haben wir der Gala ein bisschen Frieden beschert. Wir wollen ja nicht, dass Krone die Feier verdirbt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78346] = { id = 78346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak-Zephir", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78347] = { id = 78347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak-Zephir - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78348] = { id = 78348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde in niederen Gefilden", description = "Als wir abstürzten, wurden wir sofort von den Nerubern attackiert. Wir hätten fast alle verloren, wenn nicht jemand eingegriffen hätte.\n\nIch weiß nicht, wer - oder was - uns geholfen hat. Aber wenn es auch nur einen Funken Hoffnung gibt, dass wir an diesem Ort Verbündete haben, dann müssen wir diesen Funken schüren und dürfen nicht aufgeben.", sourceObjective = "Durchsucht die Atemgrube nach Eurem mysteriösen Beschützer.", completion = "Ah! Ihr habt überlebt. Ausgezeichnet. Ihr habt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[78349] = { id = 78349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Drak-Zephir - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78350] = { id = 78350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden sterben nie", description = "Verdammt noch mal! Wir haben übereilt gehandelt, und jetzt zahlen meine Leute den Preis dafür.\n\nEs war dumm von uns, zu glauben, dass die Neruber nicht auf einen Überfall vorbereitet wären. Arathisoldaten sind aus hartem Holz geschnitzt, aber sogar sie werden Schwierigkeiten haben, einen Absturz einfach so wegzustecken.\n\nIch werde alle hier beschützen. Bitte, geht hinaus ins Feld und rettet so viele Leute, wie Ihr könnt.", sourceObjective = "Helft zwölf verwundeten Luftrittern.", completion = "Ich danke Euch, {name}, im Namen von jenen, die Ihr gerettet habt. Niemand hat es verdient, alleine in der Finsternis zu sterben, und noch weniger an einem Ort wie diesem.", sourceObjectiveStatus = "unverified-source-field" }
quests[78352] = { id = 78352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freie Atemwege", description = "Ehrlich gesagt ist es mir egal, was die Neruber im Schilde führen. Sie sind nicht die ersten Emporkömmlinge, die nach Macht streben, und sie werden sicher nicht die letzten sein. Das Problem ist nur, wie sie es anstellen. Ich fürchte, wenn sie sich an dem Schwarzen Blut zu schaffen machen, gefährden sie nicht nur das empfindliche Ökosystem von Khaz Algar.\n\nWir müssen dafür sorgen, dass sie nie wieder in diese Grube zurückkehren. Ihre Ausrüstung ist immer noch in der Grube verstreut. Zerstört davon so viel wie möglich.", sourceObjective = "Zerstört 8 Stück nerubischer Ausgrabungsausrüstung überall in der Atemgrube.", completion = "<Orweyna blickt mürrisch.>\n\nDie Neruber sind ein kühnes Volk, aber das scheint selbst für ihre Verhältnisse extrem.", sourceObjectiveStatus = "unverified-source-field" }
quests[78353] = { id = 78353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürchtet das alte Blut", description = "Dies ist nicht der richtige Ort für eine lange Rede, also werde ich mich kurzfassen.\n\nDiese Wurzeln, die Ihr hier seht, sind Teil von etwas viel Größerem, und es ist meine Aufgabe, sie zu beschützen. \n\nFalls Ihr es noch nicht bemerkt habt, trieft dieser Ort nur so von Schwarzem Blut. Wenn wir nicht handeln, wird es sich noch weiter ausbreiten.\n\nIhr sucht Verbündete? Gut. Dann helft mir, diesen Ort zu läutern und diese Wurzeln zu beschützen, und ich werde Euch zumindest anhören.", sourceObjective = "Helft dabei, die Atemgrube zu säubern.", completion = "Dank deines Schweißes und meiner Zauberei konnten wir das Problem zumindest auf diese verseuchte Höhle begrenzen.\n\nDennoch, was für eine Katastrophe. Wenn schon eine Höhle von diesem Zeug Derartiges anrichten kann, erschaudere ich bei dem Gedanken, was die Neruber mit noch mehr davon anstellen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78354] = { id = 78354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leitfaden", description = "<Die Worte auf dem Pergament wirken nicht wie geschrieben, sondern als wären sie eingebrannt worden. Ein Hauch von Gift brennt in Eurer Nase.>\n\nBlind und einsam taumelt Ihr durch die Finsternis. Ich biete Euch einen Faden, an den Ihr Euch halten könnt.\n\nFolgt ihm, wenn Ihr Eure Verbündeten finden wollt.", sourceObjective = "Folgt der Spindel.", completion = "Ihr seid also meinem Faden bis zum Ende gefolgt.\n\nUm unser beiden willen bin ich froh, dass Euer Eifer stärker ist als Eure Überlebensinstinkte.", sourceObjectiveStatus = "unverified-source-field" }
quests[78355] = { id = 78355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz eines zerschlagenen Traums", description = "<Ihr spürt ein Echo uralter Sorge, Furcht und Wut, als Ihr in die wirbelnden Tiefen der seltsamen Sphäre blickt. Vielleicht weiß Merithra mehr darüber?>", sourceObjective = "Findet Merithra in Amirdrassil, Hoffnung des Traums, und zeigt ihr die verdrehte Träumende Essenz.", completion = "Interessant... Ich spüre die uralten Hoffnungen und Träume des armen Knorrenwurzel im Inneren, aber sie wurden durch Igiras schändliche Grausamkeiten verfinstert und verderbt. Als ob der Traum selbst versucht, ihre Bemühungen in dieser Essenz zu isolieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[78356] = { id = 78356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NICHT BENUTZEN", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78357] = { id = 78357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träumerische Drachenbeobachtung" }
quests[78358] = { id = 78358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappen des Drachen", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78363] = { id = 78363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wappenrock Eurer Träume", description = "<Melsysra drückt Euch eine leicht feuchte Notiz in die Hand.>\n\n{name}, wir sind Euch unendlich dankbar für alles, was Ihr für uns getan habt. Wenn Ihr für Euren Einsatz gebührend belohnt werden wollt, findet Ihr mich im Zentrallager.\n\n- Amrymn", sourceObjective = "Sprecht mit Hüter Amrymn im Zentrallager.", completion = "Ihr habt Euch diesen Wappenrock mehr als verdient. Habt Ihr Euch das genauso in Eurem Traum vorgestellt?", sourceObjectiveStatus = "unverified-source-field" }
quests[78364] = { id = 78364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappen des Drachen", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78369] = { id = 78369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "Sieht aus, als hätte Hummel Sicherheitsleute angeheuert. Aber keine Sorge, ich hab ein paar spezielle \"Geschenke\" dabei.\n\n<Schnappbolz zeigt auf die unbeschriftete Kiste.>\n\nBomben. Ich hab Bomben dabei.\n\nJetzt ist Schluss mit lustig. Nehmt diese Bomben und jagt damit Krone und ihre Vorräte in die Luft. Zeigt ihr, was ehrliche Handarbeit bedeutet. Sobald wir ihrem schmutzigen Geschäft das Handwerk gelegt haben, können wir uns um Hummel kümmern.", sourceObjective = "Nutzt die Handwerk-Bon-Bomben, um Vorräte der Chemiemanufaktur Krone zu zerstören und Mitglieder der Chemiemanufaktur Krone auszuschalten.", completion = "Junge, ich steh so sehr auf gutes Feuerwerk! Hervorragende Arbeit, {name}. Das dürfte sie wenigstens etwas ausbremsen.\n\nJetzt müssen wir uns nur noch um Hummel kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78370] = { id = 78370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beklemmende Klauen" }
quests[78372] = { id = 78372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappen des Drachen", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78373] = { id = 78373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Traum dankt Euch", description = "<Melsysra drückt Euch eine leicht feuchte Notiz in die Hand.>\n\n{name}, Euer Beitrag zu diesem Traum ist unermesslich. Bitte trefft mich im Zentrallager, damit wir Euch belohnen können.\n\n- Amrymn", sourceObjective = "Sprecht mit Amrymn im Zentrallager.", completion = "Vielen Dank. Für alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[78374] = { id = 78374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugsteine", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78377] = { id = 78377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenzählen" }
quests[78379] = { id = 78379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gestank der Rache", description = "Das wird erst vorbei sein, wenn wir den Boss ausschalten.\n\nApotheker Hummel hat sich mit seinen Spießgesellen in der Burg Schattenfang verschanzt. Er arbeitet an der nächsten Charge von giftigem Parfüm und er wird damit ganz Sturmwind auslöschen, wenn wir ihn seine Forschung durchziehen lassen.\n\nIhr macht am besten das, was Ihr am besten könnt. Dringt dort ein und durchkreuzt seine Pläne, bevor wir alle als Leichen mit Lavendelduft enden.", sourceObjective = "Sprecht mit Schnappbolz, um an dem Kampf gegen die Chemiemanufaktur Krone teilzunehmen und Apotheker Hummel zu besiegen.", progress = "Wollt Ihr mal sehen, was Hummel da zusammenkocht? Ich kann Euch aber garantieren, dass es nicht so schön wird, wie es riecht.", completion = "Klingt, als wärt Ihr gerade noch rechtzeitig dort eingetroffen. Fantastische Arbeit!\n\nHätte Hummel die gesamte Gala vergiftet, hätte das richtig übel werden können.\n\nSagen wir einfach, dass das unser Geschenk an sie ist, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[78380] = { id = 78380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich träume von Drachen" }
quests[78381] = { id = 78381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Träume", description = "Noch ein unglaublicher Fund, {name}!\n\nDiese Hälfte eines Funkens der Träume könnte sich für Eure Fertigungspläne als hilfreich erweisen, wenn Ihr sie mit einem Gegenstück vereint.\n\nSucht Euch einen weiteren gesplitterten Funken der Träume und kombiniert beide.", sourceObjective = "Findet einen weiteren gesplitterten Funken der Träume.", progress = "Habt Ihr einen weiteren gesplitterten Funken der Träume gefunden?", completion = "Das sind tolle Neuigkeiten! Wenn Ihr weitere findet, könnt Ihr sie kombinieren und damit Eure hergestellte Ausrüstung verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78383] = { id = 78383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktischer Vorteil", description = "Um dem Ganzen noch die Krone aufzusetzen, haben sie mich entwaffnet. Ich gehe nicht ohne meine Klingen!\n\nWährend wir sie suchen, haltet die Augen nach Hinweisen darauf offen, was hier vor sich geht. Nach allem, was uns einen Vorteil gegen die Neruber verschaffen könnte.\n\nEs hat sich etwas Merkwürdiges ereignet, das uns Gelegenheit zur Flucht ermöglicht. Ich habe das Gefühl, dass es sich dabei um etwas handeln könnte, dass wir ausnutzen können.", sourceObjective = "Findet Finns Klingen und 3 Geheiminformationen der Neruber bei Streitkräften der Kaheti in Rak-Zakaz.", progress = "Hier muss irgendetwas sein, das für die Weberin von Wert ist...", completion = "Ich denke, das genügt, um es bei der Weberin gegen das Gegengift einzutauschen. Anub'azal ist eine Spur, der wir nachgehen sollten. Vielleicht wird er mit uns einen Handel eingehen wie die Weberin. Vielleicht erhalten wir von ihm etwas noch Besseres.\n\nKlingt für mich nach einem Risiko, das es sich einzugehen lohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78384] = { id = 78384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Licht", description = "Anduin hat diesen Schwarm überlebt. Ich zweifle keine Sekunde daran. Und trotzdem sind die Neruber überall, und er ist nur ein einziger Mensch.\n\nWo auch immer er hingehen mag, wo auch immer er festgehalten wird, ich werde ihn finden. Findet für mich ein Zeichen, egal welcher Art, dass er noch am Leben ist. Das ist alles, was ich brauche, um ihm bis ans Ende Azeroths zu folgen.", sourceObjective = "Sucht nach Hinweisen darauf, dass Anduin überlebt hat.", progress = "Ihr seid zurück.\n\nIhr bringt sicher Neuigkeiten.", completion = "Ein zerschmetterter Handschuh und ein paar Stofffetzen... aber keine Leiche. Immerhin. Er ist am Leben und hat sich gewehrt.\n\nTrotzdem ist das nicht viel. Die meisten Waldläufer wären verständlicherweise ratlos.\n\nGlücklicherweise bin ich nicht wie die meisten Waldläufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[78385] = { id = 78385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Traumsaat", sourceObjective = "Sprecht hier mit Sylvia Flüsterblüte: [zone].", completion = "Bitte nehmt diese Traumsaat als Dankeschön für alles, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78386] = { id = 78386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smaragdwiedererwachen", description = "<Melsysra drückt Euch eine leicht feuchte Notiz in die Hand.>\n\n{name}, wir haben herausgefunden, wie man Kreaturen in den Traum bringt. Sprecht mich an, wenn Ihr mehr darüber wissen wollt!\n\n- Elianna", sourceObjective = "Sprecht mit Elianna im Zentrallager.", completion = "Um etwas zu tun, müsst Ihr es zunächst träumen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78387] = { id = 78387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pralle Traumsaat", completion = "Bitte nehmt diese Traumsaat als Dankeschön für alles, was Ihr für uns getan habt." }
quests[78388] = { id = 78388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gigantische Traumsaat", completion = "Bitte nehmt diese Traumsaat als Dankeschön für alles, was Ihr für uns getan habt." }
quests[78389] = { id = 78389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaulauf der Schöpfer", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78390] = { id = 78390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaulauf der Schöpfer - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78391] = { id = 78391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaulauf der Schöpfer - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78392] = { id = 78392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verhedderte Netz", description = "Glaubt mir, ich habe nicht vor, Euch wie einen frisch geschlüpften Käfer in der Dunkelheit herumhüpfen zu lassen. Es wäre nicht gut, wenn mein kleines Häppchen von einem ausgehungerten Höhlenbohrer aufgefressen würde.\n\nIhr müsst Euch informieren, Liebes. Eure Verbündeten haben sich in einem sengenden Wandteppich verfangen. Nur wenn Ihr Euch mit den einstigen Architekten vertraut macht, könnt Ihr sie befreien.\n\nZu Eurem Glück stelle ich Euch einige meiner persönlichen Ressourcen zur Verfügung.", sourceObjective = "Studiert die Archive der Weberin.", progress = "Seid Ihr noch nicht fertig? Die Gestaltung der Archive ist doch wirklich recht elegant. Einfach tippen und zuhören. Selbst ein spindeldürres Ding, wie Ihr es seid, sollte sich darin zurechtfinden, da bin ich mir sicher.", completion = "Nun heißt es Vorhang auf für Euch. Ich fürchte, Ihr betretet die Bühne mitten im Stück, aber keine Sorge! Ihr habt noch genug Zeit, um in eine wichtige Rolle zu schlüpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78393] = { id = 78393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein scheinbarer Aufschub", description = "Ihr habt seit Eurer unglücklichen Schiffsreise ziemlich viel durchgemacht, was? Keine Sorge, kleines Häppchen. Ihr werdet feststellen, dass meine Freunde hier sehr zuvorkommend sind, selbst zu jemandem mit Euren Vorlieben, so seltsam sie auch sein mögen.\n\nNehmt Euch bitte einen Moment Zeit, um Euch umzusehen. Nutzt die vielen Annehmlichkeiten, die ich biete. Mit etwas Glück werdet Ihr die dringend benötigte Ruhe finden.\n\n... Oh, aber passt auf, dass Ihr Euch nicht zu schnell bewegt. Abrupte Bewegungen, Ihr versteht schon.", sourceObjective = "Erkundet den Hort der Weberin.", progress = "Keine Angst! Ich bin mir fast sicher, dass meine Gefährten Euch nicht fressen werden.", completion = "Nun? Seid Ihr nicht beeindruckt von meiner Gastlichkeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[78398] = { id = 78398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Mineralien...", description = "Ich glaube, wir können die hier durchbringen, {name}. Aber wir müssen den Boden revitalisieren, damit diese Pflanze gedeihen kann.\n\nMacht Euch auf zum Auge von Ysera und sammelt Fischgräten von den Tiefenschlundlauerern in den Tiefen des Wassers. Sie sind reich an Mineralien und leicht kompostierbar. Sie allein werden den Boden nicht wieder fruchtbar machen, aber sie sind ein guter Anfang.", sourceObjective = "Sammelt Fischgräten von den Tiefenschlundlauerern.", progress = "Habt Ihr bekommen, wonach ich gefragt habe? Ohne dem wird die Pflanze nicht gedeihen.", completion = "Ja, das ist es. Ich weiß es zu schätzen, dass Ihr Euch die Mühe macht, sie zu sammeln.\n\nDiese Form ist nicht optimal zum Schwimmen, wisst Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[78421] = { id = 78421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Träume", description = "Es scheint, als würde das Gefüge des Traums selbst Eindringlinge abwehren und Schatten ihrer Träume in der Form von Essenzen hinterlassen. So nahe an Amirdrassil hinterlassen selbst Eure eigenen Taten flüchtige Echos der Macht.\n\nMit genug Zeit können wir vielleicht die volle Kraft dieser Echos erwecken, und sie gegen Fyrakk einsetzen. Besiegt die Eindringlinge, wo auch immer Ihr sie findet, und kehrt zu mir zurück, nachdem Ihr genug Macht des Traums aufgenommen habt.", sourceObjective = "Sammelt Echo der Ephemera und die Träume der Eindringlinge von Amirdrassil.", progress = "Der Traum hat viele Ebenen, manche davon sind sehr fragil. Ich befürchte, dass sogar die Anwesenheit der Verteidiger dieses unveränderliche Land verändert.", completion = "Das sollte genügen, um die Macht zu erwecken, die in diesen feurigen Essenzen schlummert. Wir sind endlich bereit, die Kraft der Eindringlinge gegen sie selbst zu wenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78427] = { id = 78427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtige Kisten", description = "Der Angriff auf den Traum wird immer stärker.\n\nWir sind verzweifelt auf der Suche nach Handelswaren und Vorräten zur Unterstützung der Verteidigung. Sogar eine einzige Kiste kann an der Front den Unterschied machen.\n\nVashonir kann Euch helfen, die Lieferungen einzupacken. Bringt diese dann zu mir.\n\nMöge Elune über Euch wachen, <Verteidiger/Verteidigerin> des Traums.", sourceObjective = "Verpackt 1 Warenlieferung mit Vashonir im Zentrallager.", progress = "Vashonir wird Euch durch die Vorbereitung der Lieferungen unterstützen.", completion = "Wir sind für jeden Beitrag Eurerseits dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[78428] = { id = 78428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kiste der Kunst", sourceObjective = "Verpackt 5 Warenlieferungen mit Vashonir im Zentrallager.", progress = "Vergesst nicht, Vashonir zu bitten, Euch bei der Vorbereitung der Lieferungen zu helfen!", completion = "Danke, {name}. Wir stehen tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[78429] = { id = 78429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Träume, erwacht", description = "Seid Ihr bereit, {name}? Ich werde die Essenzen ihrer feurigen Träume für Euch verschmelzen. Konzentriert Euch auf das Echo der Ephemera, das Ihr gesammelt habt, um die darin verborgene Macht zu wecken. Zeigt Fyrakk, dass er die Kraft des Traums fürchten sollte!", sourceObjective = "Erweckt die Macht der verschmolzenen Essenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[78430] = { id = 78430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiese grüne Infusionsmaschine", description = "Erfreut, Euch kennenzulernen. Ich bin Elianna, ein Traumforscher.\n\nEin seltsames Phänomen wird seit kurzem im Traum beobachtet. Die Kreaturen hier hinterlassen Fragmente von Traummagie.\n\nIch bin neugierig auf die Effekte, die solche Magie in konzentrierten Dosen hervorrufen könnte. Aber ich brauche jemanden, der sie für mich extrahiert.\n\nEs gibt einige problematische Peitscher und Schotlinge südlich von hier. \n\nEinige von ihnen sollten für eine geringe Infusion genügen.", sourceObjective = "Tötet 6 Schotlinge und Peitscher im Smaragdgrünen Traum.", progress = "Habt Ihr mir genug Traumenergie gebracht?", completion = "Ausgezeichnet! Wir sollten in der Lage sein, die Infusion durchzuführen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78431] = { id = 78431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünes Traumteam", description = "Äußerst interessant!\n\nEs ist mir gelungen, die Traumenergie, die Ihr mir gebracht habt, zu konzentrieren.\n\nHiermit können wir die Infusion durchführen!\n\nNa los, ich sehe zu.", sourceObjective = "Führt eine geringe Trauminfusion durch.", progress = "Na los! Ich möchte die Infusion bei Rithro beobachten.", completion = "Ausgezeichnet! Es hat funktioniert!", sourceObjectiveStatus = "unverified-source-field" }
quests[78434] = { id = 78434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenreiterrennen - Ysera-Einladungsturnier" }
