quests[78443] = { id = 78443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallsangkrise - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78444] = { id = 78444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiger Verbündeter: Traumwächter", description = "So viel Veränderung von Dingen, die unveränderlich bleiben sollten...\n\nDer Traum hat nur selten so viel Aufruhr gesehen. Er ist dazu bestimmt, ein Ort des Friedens zu sein. Des Lebens.\n\nChampion, wir brauchen alle Hilfe, die wir bekommen können. Ich bitte Euch, auszuziehen und Eure Unterstützung in den Weiten des Traums anzubieten.\n\nIch habe keinen Zweifel daran, dass der Traum seine Gaben zum Dank mit Euch teilen wird.", sourceObjective = "Helft den Traumwächtern und ihren Verbündeten im Smaragdgrünen Traum.", progress = "Nehmt Euch die Zeit, innezuhalten und an den Blüten des Traums zu schnuppern. Das wird Euer Leben bereichern.", completion = "<Hüter Amrymn holt tief Luft.> \n\nDer Wind hat sich beruhigt. Frieden kehrt in den Traum zurück, wenn auch langsam.\n\nAlle, die diesen Ort pflegen und verteidigen, danken Euch, Held.", sourceObjectiveStatus = "unverified-source-field" }
quests[78446] = { id = 78446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Superblüte", description = "Mit dem Leben im Smaragdgrünen Traum erblüht auch der knospende Weltenbaum Amirdrassil.\n\nDas Ritual des uralten Fichtenkrone ruft mächtige Lebensenergien rund um den Baum hervor und fördert sein Wachstum. Je mehr Hände helfen, Amirdrassil zu schützen und zu pflegen, desto eindrucksvoller wird seine Blüte sein!\n\nBitte unterstützt Fichtenkrone auf der Reise.", sourceObjective = "Reist in den Smaragdgrünen Traum und helft Fichtenkrone, eine Superblüte zu erschaffen. Setzt Eure Bemühungen fort, das Valdrakkenabkommen und seine Verbündeten auf allen Dracheninseln zu unterstützen.", progress = "Ich hoffe, Ihr leidet nicht an Allergien.", completion = "Ah, ich kann von hier aus fast die Blumen im Wind riechen!\n\nBitte nehmt dieses bescheidene Geschenk an und seid Euch unserer Dankbarkeit gewiss.", sourceObjectiveStatus = "unverified-source-field" }
quests[78447] = { id = 78447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Smaragdfülle", description = "Der Smaragdgrüne Traum leidet unter den Kräften der Inkarnation Fyrakk. In diesem Aufruhr haben einige der Samen Schwierigkeiten, Wurzeln zu schlagen.\n\nWenn Ihr den Traum erforscht, werdet Ihr sicher einige ganz besondere Samen sammeln. Pflanzt sie in den Boden ein und pflegt sie, bis sie erblühen. Man sagt, dass sie einen dann reichlich beschenken werden.\n\nZieht los und helft dem Leben, im Smaragdgrünen Traum zu erblühen!", sourceObjective = "Reist in den Smaragdgrünen Traum und pflanzt 3 Traumsaaten beliebiger Qualität in die Erde der Smaragdfülle. Traumsaat kann bei den meisten Aktivitäten im Traum verdient werden. Setzt Eure Bemühungen fort, das Valdrakkenabkommen und seine Verbündeten auf den Dracheninseln zu unterstützen.", progress = "Ich frage mich, welche Gaben eine Blume spenden kann?", completion = "Der Traum ist ein so seltsamer Ort!\n\nBitte nehmt dieses bescheidene Geschenk an, zusammen mit unserem aufrichtigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[78452] = { id = 78452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkungen - Aktivieren" }
quests[78454] = { id = 78454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenödendrachenflug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78455] = { id = 78455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenödendrachenflug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78456] = { id = 78456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenödeflug - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78457] = { id = 78457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Dornogal", description = "Ich bin Merrix, Ratsvorsteher von Dornogal.\n\nIch weiß Eure Hilfe zu schätzen, insbesondere vor dem Hintergrund Eurer nervenaufreibenden Art des Eintreffens. Ihr müsst Sturmwehr Baelgrim vergeben, es ist Teil seiner Weisung, argwöhnisch zu sein.\n\nEine formelle Art der Unterhaltung über unsere Situation ist angebracht. Wenn Ihr es den Nerubern ebenfalls heimzahlen wollt, dann kommt zur Gründungshalle. Baelgrim und ich müssen die bislang gesammelten Daten auswerten.\n\nIn der Zwischenzeit seid Ihr mein Gast. Nehmt meinen Ring. Er wird Euch den Zugang zu den Annehmlichkeiten von Dornogal ermöglichen.", sourceObjective = "Trefft die verschiedenen irdenen Einwohner in Dornogal.", progress = "Der Angriff scheint sich auf den Kernweg zu konzentrieren. Der Rest der Stadt ist sicher, aber wir sollten auf alles vorbereitet sein.", completion = "Baelgrims Wachsamkeit hat uns all die Jahre über beschützt, aber heute benötigen wir Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78458] = { id = 78458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enthemmung der Ernter - Aktivator" }
quests[78459] = { id = 78459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lage der Nation", description = "Ich gebe es nur ungern zu, aber die Neruber haben uns kalt erwischt.\n\nUnser Fokus lag darauf, Dornogal und unsere schwindende Bevölkerung zu versorgen.\n\nDank Sturmwehr Baelgrims unerschütterlichem Stolz sind seine Sturmreiter und er noch immer unverzichtbar im Kampf, aber ihnen steht das Wasser schon jetzt bis zum Hals und sie sind keine Baumeister.\n\nDer Kernweg ist so stark beschädigt, dass wir ihn nicht mehr reparieren können.\n\nAber... das war nicht immer so. Wenn Ihr das verstehen wollt, muss ich Euch wohl mehr über uns und unsere Geschichte erzählen.", sourceObjective = "Erfahrt mehr über den Rat von Dornogal von Merrix.", progress = "So vieles ging verloren.", completion = "Wir sind entzwei gebrochen. Und nun wird unsere Bestimmung auf die Probe gestellt. Titanen, gebt uns Stärke...", sourceObjectiveStatus = "unverified-source-field" }
quests[78460] = { id = 78460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdbebenzentrum", description = "Ich habe mein Volk enttäuscht. Der Kernweg ist unpassierbar. Dornogals Lebensader zu den Schallenden Tiefen wurde gekappt, wie auch der weiterführende Pfad.\n\nDie Neruber werden die Quittung dafür noch bekommen. Das ist mein Edikt und mein Wille.\n\nIch werde mich vergewissern, ob der Ratsvorsteher noch funktionsfähig ist, und ihn ins Archiv bringen. So die Titanen es wollen, wird Sprecherin Brinthe dort sein.\n\nAber die Eingeschworenen sind noch immer in Gefahr. Wenn Ihr eine Allianz mit uns anstrebt, dann beseitigt den Schutt und leistet den Überlebenden Hilfe.\n\nIch erwarte Euch im Archiv.", sourceObjective = "Entfernt die Trümmer und rettet Irdene auf dem Weg zum Archiv.", progress = "Das Archiv sieht intakt aus, zum Glück. Wir müssen um jeden Preis dafür sorgen, dass das auch so bleibt.", completion = "Ihr seid hier.\n\nGut.\n\nIst das ein Erinnerungsedelstein, den Ihr da habt? Ihr hättet die Ruhe unserer Toten nicht stören dürfen.\n\nAber... Ihr habt ihn an den richtigen Ort gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78461] = { id = 78461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vierte Sitz", description = "Da mein Vater und Anduin geschwächt sind und Alleria nirgends auffindbar ist, liegt es wohl an uns, {name}, den Weg für Thrall und Jainas Armee freizumachen, wenn wir uns an den Nerubern und Xal'atath rächen wollen.\n\nAber ohne den Kernweg führt kein Weg zu ihnen. Und ohne die Hilfe der Irdenen können wir den Kernweg nicht reparieren.\n\nWenn Merrix davon überzeugt ist, dass Adelgonn und ihre \"Freien\" die einzigen sind, die den Kernweg reparieren können, dann müssen wir sie aufspüren.\n\nDas erfordert mein überzeugendstes Lächeln und diplomatisches Geschick. Begleitet Ihr mich, {name}?", sourceObjective = "Findet Adelgonn in Freyholtz auf der Insel von Dorn.", progress = "Wenn Ihr zu Baelgrim gehört, müssen der Rat und die Eingeschworenen Euch auf unserem Land akzeptiert haben.", completion = "Mir bleibt wohl gar keine andere Wahl, als Euch und Baelgrim anzuhören.", sourceObjectiveStatus = "unverified-source-field" }
quests[78462] = { id = 78462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos des Mitgefühls", description = "Das Letzte, was ich heute erwartet hätte, war, Baelgrim zu sehen... von seiner Hilfe ganz zu schweigen. Aber ich schätze, da der Kernweg beschädigt ist, bleibt ihm keine andere Wahl. Ich... weiß nicht, wie ich dies verarbeiten soll. Es ist nur logisch, es zu akzeptieren.\n\n<Adelgonn beginnt, das fungianische Material in ihren steinernen Händen zu zermalmen. Es wird beunruhigend schnell zu einer Knetmasse.>\n\nHier. Mischt das mit dem Matsch und tragt es bei den Verletzten auf.", sourceObjective = "Heilt 5 Bewohner der Irdenen in Freyholtz.", progress = "Wir haben bereits Tiere und Elementare zurückgeschlagen, aber Neruber? Mein Volk besteht aus Handwerkern und Bergleuten, nicht Kriegern.", completion = "<Adelgonn blickt Moira, Baelgrim und zuletzt Euch abschätzend an.>\n\nIch... danke Euch. Es ist lange her, dass ich Hilfe von Fremdlingen erhalten habe. Oder von den Eingeschworenen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78463] = { id = 78463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bausteine", description = "Der Steinbruch wurde von Fungianern überrannt. Alle Stollen sind eingestürzt und wir haben keine Zeit, sie zu säubern und dann rundzuerneuern!\n\nAllerdings... habe ich auf dem Weg hierher eine Menge Erz auf dem Boden rumliegen sehen. Das wäre ein Anfang, wenn wir den Kernweg reparieren wollen, aber...\n\n<Baelgrim seufzt und blickt mit grimmiger Miene auf die verletzten freien Irdenen.>\n\nIch werde hier gebraucht. Bei Adelgonns Leuten. Meinen Leuten. Könnt Ihr an meiner statt das Erz sammeln?", sourceObjective = "Sammelt 20 Einheiten glitzerndes Erz in der Erzgrube.", progress = "Sammelt so viel Erz, wie Ihr könnt. Der Kernweg ist immer noch meine Priorität, aber diese Verletzten brauchen sofortige Hilfe.", completion = "Es ist nicht viel, aber dieses Erz sollte helfen, den Kernweg zu stabilisieren.\n\nMit Adelgonns Hilfe werden wir den Steinbruch und die Minen zurückerobern und eine Versorgungsstraße nach Dornogal etablieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[78464] = { id = 78464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taucht in die Erde ein", description = "Der Angriff der Neruber, Euer meteorhafter Absturz...\n\nUnd jetzt ist auch noch Baelgrim hier?\n\nBaelgrim braucht mehr Helfer für seinen Kernweg, aber selbst wenn ich wollte, könnte ich ihm nicht helfen. Während wir hier reden, stirbt mein Volk. Einige wurden beim Angriff von den Nerubern verschleppt.\n\nIhr seid nicht der erste Fremdling, den ich kennengelernt habe. Einer dieser Zwerge, so klein wie Moira, war vor Kurzem hier und ist den Nerubern schnurstracks hinterher. Er hat den Pfad nach Westen genommen, der zu einer Höhle in der Nähe führt.\n\nIch stünde in Eurer Schuld, wenn Ihr meine Leute retten würdet.", sourceObjective = "Schließt die Tiefe \"Erdwühlerminen\" in der Nähe von Freyholtz ab.", progress = "Die Minen waren schon immer gefährlich, selbst als die Steingebunden dort gearbeitet haben. Seid vorsichtig.", completion = "Ich danke Euch, dass Ihr meine Leute aus den Fängen der Neruber gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78465] = { id = 78465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golgrins Insel", description = "Da wir nun die Opale haben, können wir Brinthe auf Golgrins Insel treffen.\n\nSie arbeitet dort wohl an einem Projekt, bei dem ich ihr helfen soll.\n\nWas es wohl sein mag?", sourceObjective = "Trefft Euch mit Dagran auf Golgrins Insel auf der Insel von Dorn.", completion = "Eine archäologische Ausgrabungsstätte? Ein Titanengewölbe?\n\nDas hat Brinthe nicht erwähnt!", sourceObjectiveStatus = "unverified-source-field" }
quests[78466] = { id = 78466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten mit Aroma - Aktivieren" }
quests[78467] = { id = 78467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energetische Jagd", description = "Ich bin froh, dass Dagran Euch hergebracht hat. Ich benötige Hilfe bei einem gefährlichen Unterfangen.\n\nIch habe die kürzlich in dieser Ausgrabungsstätte gefundene Titanenkonsole mit Dagrans Opalen repariert.\n\nDie Eingeschworenen wollten schon lange mehr über die Titanen erfahren und Aufzeichnungen rekonstruieren, die im Archiv nicht zugänglich waren... oder sogar noch aus der Zeit vor seiner Errichtung stammen.\n\nDiese Schalttafel könnte uns Antworten liefern, wenn wir sie wieder zum Laufen bringen.\n\nNehmt dieses Gerät, das ich gebaut habe. Es führt Euch zu titanischen Energiezellen, mit denen wir es jetzt wieder mit Energie versorgen können.", sourceObjective = "Sammelt 3 Energiezellen auf Golgrins Insel.", progress = "Ohne Energie können wir die Konsole nicht wieder zum Laufen bringen.", completion = "Gut gemacht, {name}.\n\nJetzt brauche ich Dagrans Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78468] = { id = 78468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Archiv", description = "Der Erinnerungsedelstein, den Ihr geborgen habt, ist genau das, was sein Name vermuten lässt. Er enthält die Erinnerungen und Direktiven eines Irdenen sowie alle unsere Edikte.\n\nDieses Gebäude hier, das Archiv, ist der Nexus unserer Zivilisation. Hier werden die Erinnerungen eines Irdenen am Ende seiner geplanten Rotation getauscht, katalogisiert und gespeichert.\n\nMit dem von mir entwickelten Kodex können wir auf eine oder zwei Erinnerungen in einem Erinnerungsedelstein zugreifen. Nehmt ihn und greift damit auf den Erinnerungsedelstein zu, den Ihr gefunden habt.", sourceObjective = "Nutzt den Prismatischen Kodex, um die Inhalte eines Erinnerungsedelsteins anzusehen. Bringt dann den Erinnerungsedelstein zurück zum Archivspeicher in den Archiven.", progress = "Die Bedienungsanleitung ist einfach: Setzt den Edelstein in das Gerät und eine Erinnerung wird abgespielt.", completion = "Es ist... beruhigend, dass Odon im Archiv erhalten bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78469] = { id = 78469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präriefieber", description = "Ich hätte Kodun vorhin besuchen sollen, aber ich bin so versteinert wie ein lebloser Fels. Der Angriff auf das Dorf war... lähmend.\n\n<Hreka holt tief Luft und konzentriert sich auf die Form eines anderen Krugs.>\n\nKönntet Ihr mir einen Gefallen tun und diese Krüge bei Kodun abgeben? Er ist nur einen Steinwurf entfernt, im Töpferwarenladen des Dorfes. Ich muss dieses Ding hier fertigmachen bevor der Ton trocknet.", sourceObjective = "Untersucht Hrekas Tonkrüge und liefert sie dann bei Kodun in Freyholtz ab.", progress = "Seid Ihr einer der Fremdlinge aus dem Absturz am Strand?", completion = "<Kodun dreht die Keramik vorsichtig um.>\n\nPerfekt abgerundet, keine Risse, eine glatte Tülle... Hreka hat es mal wieder geschafft. Sie macht im Ort die besten Töpferwaren.", sourceObjectiveStatus = "unverified-source-field" }
quests[78470] = { id = 78470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Proszenium", description = "Die Neruber greifen die Irdenen wieder an. Wir müssen diesem Schwarm folgen!\n\nIch fürchte, dass wir in der Unterzahl sind, aber wenn die Irdenen zusammenkommen und sich hinter uns stellen...\n\nDann haben wir vielleicht eine Chance.", sourceObjective = "Reist zum Proszenium auf der Insel von Dorn.", completion = "Die Verwundeten! Die Neruber treten auf die Irdenen ein, wenn sie am Boden liegen.\n\n<Moira deutet plötzlich auf die Mitte des Schlachtfelds.>\n\nDa! In der Mitte ... Ist das Zirix? Schon wieder? Und ... Alleria?\n\nOh, die Kraft des Berges sei mit mir ... Wir müssen ihnen helfen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[78471] = { id = 78471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konvergenz", description = "Wir wissen, dass die Neruber gemeinsame Sache mit Xal'atath machen. Und wir haben eine recht klare Vermutung, warum sie uns – und Dalaran – angegriffen haben.\n\nSie scheinen es darauf abgesehen zu haben, die Irdenen zu zerstören – sogar jetzt lassen sie nicht locker.\n\nAber wieso? Ist der Kernweg der Schlüssel und seine Zerstörung war noch nicht genug? Vielleicht wollen sie genau das verhindern, was wir hier versuchen: den Kernweg zu reparieren.\n\nWir sollten nach Dornogal zurückkehren und zusehen, dass wir dieses Rätsel lösen.", sourceObjective = "Kehrt zur Gründungshalle in Dornogal zurück.", completion = "Der irdene Rat ist wieder vereint. Hoffentlich können sie die Vergangenheit ruhen lassen und den Kernweg reparieren.\n\nDann helfen sie uns hoffentlich mit den Nerubern – und Xal'atath.", sourceObjectiveStatus = "unverified-source-field" }
quests[78472] = { id = 78472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leuchten im Dunkeln - Aktivieren" }
quests[78473] = { id = 78473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Träume, verloren", description = "Ihr habt die strahlende Essenz verloren? Wie könnt Ihr so unachtsam mit etwas so Wertvollem umgehen... Ich kann Euch noch eine geben.", sourceObjective = "Erweckt die Macht der verschmolzenen Essenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[78499] = { id = 78499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitadellenzugabe", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78500] = { id = 78500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitadellenzugabe - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78501] = { id = 78501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zitadellenzugabe - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78504] = { id = 78504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein leicht geschütteltes Geschenk", sourceObjective = "Dieses Geschenk sieht aus, als wäre es schon ein paarmal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür einen ganz besonderen und außergewöhnlichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78529] = { id = 78529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewaltsamer Einschlag", description = "<Ihr könnt nur verschwommen sehen, während Ihr langsam wieder zu Bewusstsein kommt. Die Echos von entfernten Rufen und Schreien klingen Euch in den Ohren.\n\nDas Letzte, woran Ihr Euch erinnert: wie Dalaran, die großartige schwebende Stadt, Richtung Boden stürzt... und dann nichts als Finsternis.\n\nInmitten all der Schreie und Kampfgeräusche hört Ihr ein seltsames insektenartiges Klackern.\n\nDie Neruber haben auf Euch gewartet.\n\nIhr müsst Euch dem Kampf anschließen, aber zuerst müsst Ihr den Trümmerberg über Euch loswerden, der Euch mit seinem zermalmenden Gewicht niederdrückt.", sourceObjective = "Befreit Euch aus den Trümmern und findet die überlebenden Anführer.", completion = "{name}! Ihr habt überlebt!\n\nGut!\n\nHaltet Eure Waffen bereit. Dieser Kampf hat gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78530] = { id = 78530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Saboteure", description = "Die Neruber sind überall, {name}.\n\nEs sind zu viele von ihnen, als dass es nur Überlebende des Absturzes sein könnten. Ich habe gesehen, wie sich welche aus dem Boden herausgegraben haben.\n\nDiese Königinnenwache Zirix hat hier gewartet, um uns zu überwältigen.\n\nMacht ihnen klar, dass wir keine leichte Beute sind. Macht sie nieder!", sourceObjective = "Tötet 12 Neruber.", progress = "Wir müssen ihre Reihen ausdünnen, wenn wir hier überleben wollen.", completion = "Gute Arbeit. Und wir haben ebenfalls Fortschritte gemacht. Vielleicht können wir jetzt Druck nach vorne machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78531] = { id = 78531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dringende Bergung", description = "Wir haben größtenteils unverletzt überlebt. Aber nicht alle hatten so viel Glück.\n\nViele von jenen, die beim Absturz in Dalaran weilten, werden noch vermisst. Sie werden unsere Hilfe brauchen.\n\nSucht auf dem Schlachtfeld nach Überlebenden. Helft ihnen auf jede erdenkliche Art.\n\nWir brauchen alle im Kampf!", sourceObjective = "Helft 7 Überlebenden des Absturzes Dalarans.", progress = "Wir müssen so viele retten wie möglich.", completion = "Es ist gut zu wissen, dass viele überlebt haben.\n\nWenn diese Schlacht vorüber ist, werden wir die Leichname jener bergen, die es nicht geschafft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78532] = { id = 78532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberechenbare Artefakte", description = "In Dalaran befanden sich viele kostbare und mächtige Relikte. Beim Absturz wurden viele davon beschädigt und spielen jetzt verrückt.\n\nSie müssen zerstört werden!\n\nNehmt diese Schriftrolle. Sie enthält einen Zertrümmerungszauber. Lest die Worte laut vor und die Magie darin wird entfesselt.\n\nErstattet Jaina Bericht, wenn Ihr fertig seid. Sie wird es verstehen.", sourceObjective = "Zerstört 5 beschädigte arkane Relikte.", progress = "Es schmerzt mich, aber wir müssen diese Relikte mit Fehlfunktion zerstören!", completion = "Weitere Teile von Dalaran zu zerstören erscheint unerhört.\n\nAber Ihr und Aethas habt das Richtige getan.\n\nSie waren instabil und wir konnten das Risiko nicht eingehen, dass sie gegen uns verwendet werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[78533] = { id = 78533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichert den Strand", description = "Die Königinnenwache Zirix ist aus dem Boden aufgetaucht und hat Magni überrascht.\n\nEr befindet sich am fernsten Ende des Wracks, wo er gegen den Schwarm kämpft.\n\nMoira und ich haben versucht, ihm zu helfen, aber wir konnten sie nicht von ihm fortlocken.\n\nKommt mit mir. Magni braucht unsere Hilfe!", sourceObjective = "Findet Magni und besiegt die Königinnenwache Zirix.", completion = "Ihr mögt keine Eindringlinge sein, aber unsere Verbündeten seid Ihr auch nicht, Fremdling.\n\nWenn Ihr daran schuld seid, dass die Neruber aus ihren Löchern hervorgekrochen sind, dann seid Ihr auch für den Angriff auf Dornogal verantwortlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[78534] = { id = 78534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Dornogal", description = "Ihr habt so viel Tod und Zerstörung an unsere Küsten gebracht wie schon seit Jahrtausenden nicht mehr.\n\nAber Ihr habt auch das Blut der Neruber an Euren Händen und einen Thraegar an Eurer Seite. Das ist ausreichend, um mein Vertrauen zu erlangen – fürs Erste.\n\nMeine Sturmreiter und ich müssen zur Hauptstadt zurückkehren, nach Dornogal. Die Angriffe dort scheinen nicht abzureißen und jemand muss sich der Sache annehmen und den Grund dafür herausfinden. Fliegt mit uns. In unserer Wirbelströmung könnt Ihr mühelos durch die Lüfte gleiten.\n\nIch werde andere Sturmreiter losschicken, um Eure Verbündeten zu holen, sobald sie sicher landen können.", sourceObjective = "Trefft Euch mit Baelgrim in Dornogal, indem Ihr der Wirbelströmung des Sturmreiters folgt.\n\nDie meisten Dienstleistungen in Dornogal werden während dieser Quest nicht verfügbar sein.", completion = "Was haben die Neruber angerichtet? Und warum?", sourceObjectiveStatus = "unverified-source-field" }
quests[78535] = { id = 78535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie kommen aus der Tiefe", description = "Noch weiß ich nicht, warum Ihr hier seid, Fremdling, aber Ihr macht einen... kompetenten Eindruck auf mich, wenn es ums Abschlachten von Nerubern geht.\n\nWir Sturmreiter, die Speerspitze dieser Insel, sind ebenfalls geübt darin.\n\nDie Neruber sind schon seit langer Zeit mit uns verfeindet. Es würde mich nicht überraschen, wenn dieser Zirix mich kennt und fürchtet, mich, die Sturmwehr.\n\nDennoch könnten wir Eure Hilfe beim Schutz von Dornogal gut gebrauchen.\n\nEine Sturmkrähe steht für Euch bereit. Sitzt auf und helft uns, die Stadt von diesen Insekten zu befreien!", sourceObjective = "Schwingt Euch auf die Sturmkrähe Lokren und vernichtet Neruber in Dornogal.\n\nDie meisten Dienstleistungen in Dornogal werden während dieser Quest nicht verfügbar sein.", completion = "Ich weiß nicht, warum die Neruber zurückgekehrt sind...\n\nOder warum sie Dornogal angreifen sollten.\n\nJetzt muss ich mich darauf konzentrieren, den Schaden am Kernweg zu beurteilen.\n\nUnsere Brüder und Schwestern von den Maschinenflüsterern brauchen vielleicht unsere Hilfe und es ist der Wille der Titanen, dass der Weg ins Innere von Azeroth offen bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78536] = { id = 78536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aussichtslose Lage", description = "Bei den Titanen... Der Kernweg scheint komplett zerstört zu sein! Es wird Jahre, vielleicht Jahrhunderte brauchen, um die Trümmer zu beseitigen und den Schaden zu beheben, den die Neruber an der inneren Struktur angerichtet haben, geschweige denn, zum Kern der Welt vorzudringen.\n\nSogar noch länger, nun, da die Steingebundenen fort sind...\n\nIch muss darüber nachdenken, was zu tun ist.\n\nEure Freunde sind sicher angekommen. Sprecht mit ihnen und steht mir nicht im Weg herum.\n\nWenn wir Euch brauchen, werde ich es Euch wissen lassen.", sourceObjective = "Sprecht mit Thrall.", progress = "Der Rat muss informiert werden. Wir haben viel zu tun...", completion = "In meinen Anweisungen seid Ihr nicht vorgesehen, Fremdling.", sourceObjectiveStatus = "unverified-source-field" }
quests[78538] = { id = 78538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Anstrengungen", description = "Die Freien sind mit der Ausrüstung und den Ressourcen eingetroffen, die für die Reparatur des Kernwegs notwendig sind, zumindest für den ersten Teil der Arbeiten.\n\nDas ist ein denkwürdiger Moment. Einer für das Archiv! Adelgonn würde ich es nie sagen, aber ich denke, die Titanen hatten hier ihre Hände im Spiel...\n\nUnd jetzt ist es Zeit, dass ich meine Direktive ausführe! Ich habe einen Plan ausgearbeitet, wie wir unsere Arbeiter am effizientesten einsetzen können, und ich habe Vorräte reserviert, um sie gebührend willkommen zu heißen.\n\nBringt diese Befehle zu Adelgonns Arbeitern, damit sie endlich loslegen können. Wir werden Euch dort in Kürze treffen.", sourceObjective = "Verteilt die Aufträge von Merrix an 10 freie Arbeiter beim Kernweg.", progress = "Wir müssen sofort mit den Arbeiten beginnen.", completion = "Sogar mit so vielen Arbeitern werden die Reparaturarbeiten am Kernweg ihre Zeit dauern.\n\nWir müssen entscheiden, was wir in der Zwischenzeit unternehmen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78539] = { id = 78539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhaltende Reparaturen", description = "Da meine Sturmreiter... inaktiv sind, gibt es niemanden, der Dornogal noch beschützen könnte, abgesehen von einigen wenigen freiwilligen Friedensbewahrern. Wenn die Neruber uns erneut hier angreifen, ist Dornogal dem Untergang geweiht - und somit wir alle.\n\nEs ist unerlässlich, dass wir sie von der Stadt weglocken und ihren Kommandanten ausschalten.\n\nWir können und werden unser eigenes Netz spinnen und Zirix damit fangen.\n\nIch habe einen Plan.", sourceObjective = "Besprecht den Plan, die Neruber anzugreifen, mit Baelgrim.", completion = "Dann ist es also beschlossene Sache.\n\nWir werden uns bei der Metbrauerei Glutbräu zur Wehr setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78540] = { id = 78540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbruch zur Metbrauerei", description = "Eure Freundin, die Bogenschützin, hat recht. Wir müssen Zirix und seine Streitkräfte eliminieren, wenn wir den Kernweg schützen wollen.\n\nLasst uns sofort zur Metbrauerei Glutbräu aufbrechen.", sourceObjective = "Trefft Euch mit Baelgrim an der Metbrauerei Glutbräu.", completion = "Den Titanen sei Dank! Die Neruber haben noch nichts unternommen, um an den Met zu gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78541] = { id = 78541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Falle einrichten", description = "Mit den ganzen Glutbräufässern hier würde diese Metbrauerei heißer brennen als die Schmiedegründe.\n\nIch denke, deshalb hat Wenbrandt seine Fässer aus Starkbier und robustem Eisenholz gemacht - sie zerbrechen nicht und sie fangen auch nicht so leicht Feuer.\n\nGlücklicherweise können wir eine Reaktion aus dem Inneren hervorrufen, wenn wir die Lunten zu jedem Fass führen.\n\nDiese Seile, die die Arbeiter haben liegen lassen, sollten im Notfall dafür geeignet sein.", sourceObjective = "Verbindet 4 Seillunten mit zischenden Fässern.", progress = "Wir müssen die Glutbräufässer vorbereiten.", completion = "Zirix wird durch meine Hand fallen. Es ist meine Anweisung. Es ist mein Wille.", sourceObjectiveStatus = "unverified-source-field" }
quests[78542] = { id = 78542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierungsbereich", description = "Nun gut, Ihr könnt mein Lebenswerk in die Luft jagen, wenn das die einzige Möglichkeit ist, aber ich werde meine Arbeiter nicht in Gefahr bringen.\n\nDies war der Weg, für den wir uns alle entschieden haben, aber ich werde nicht zulassen, dass sie sich dafür dem Feuer oder den Nerubern opfern. Sagt ihnen, dass ich befohlen habe, dass sie sofort hier abhauen.\n\nUnd wenn nur ein einziger von ihnen den winzigsten Kratzer abbekommt, dann werde ich den Rat dafür zur Rechenschaft ziehen!", sourceObjective = "Holt 8 freie Arbeiter der Metbrauerei raus.", progress = "Wenn meine Arbeiter nicht in Sicherheit gebracht werden können, werde ich diesen Plan stoppen.", completion = "Es freut mich, dass sie genug Einsicht hatten, ohne viele Umstände abzuhauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78543] = { id = 78543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stich ins Spinnennest", description = "Die Metbrauerei ist evakuiert und die Sprengstoffe sind vorbereitet. Es ist Zeit, dass wir die Neruber in die Falle locken.\n\nEure Kameradin hält sich beim Nerubergraben im Norden auf. Sie hat mir gesagt, dass es ihre Anweisung wäre, über den Bau zu wachen, für den Fall, dass die Neruber etwas unternehmen, bevor wir bereit sind.\n\nBis jetzt haben sie sich nicht gerührt und wir müssen ihnen vielleicht ein wenig... gut zureden. Nehmt ein Fass mit Glutbräu zu ihrem Bau. Wenn Ihr es hineinwerft, sollte das für Unruhe in ihrem \"Nest\" sorgen.\n\nTrefft Euch danach - schnell - wieder mit uns bei der Metbrauerei.", sourceObjective = "Werft ein Fass Glutbräumet in den Nerubergraben und kehrt dann zur Metbrauerei zurück.", completion = "Der Neruberschwarm ist auf dem Weg.\n\nMacht Euch bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[78544] = { id = 78544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Donner bringen", description = "Die Neruber werden voller Wut und verletztem Stolz angreifen - und das ist genau, was wir wollen.\n\nSie werden bald die Metbrauerei überrennen, um sich für unseren Angriff auf ihren Bau zu rächen. Wir binden ihre Kräfte dort am Boden, während Ihr Euch in die Lüfte schwingt. Sobald Zirix auftaucht, um seine Armee zu kommandieren, stecken wir die Lunten an.\n\nWenbrandt hat ein paar Materialien aufgetrieben, mit denen wir die Neruber einpferchen können. Stellt sie schnell auf, dann setzen wir Euch auf eine Sturmkrähe. Los!", sourceObjective = "Haltet die Neruber an der Metbrauerei Glutbräu in Schach, bis Königinnenwache Zirix auftaucht.", completion = "Zirix ist tot. Wir haben es geschafft. Es ist vorbei. Baelgrim hat es geschafft.\n\n<Sie murmelt den letzten Satz wieder und wieder vor sich hin, als könnte sie die Geschehnisse immer noch nicht glauben.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78545] = { id = 78545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zum Kernweg zurück.", description = "Wir haben den Nerubern einen schweren Schlag versetzt. Aber Baelgrim...\n\n<Adelgonn hält einen Moment inne, um sich zu fassen.>\n\nEr hat mich mit seiner Sturheit zur Weißglut getrieben und wir haben unentwegt gestritten, aber letztendlich... war er ein Beschützer unseres Volkes, jedes einzelnen von uns.\n\nEr hat sein Leben geopfert, um die Insel von Dorn vor den Nerubern zu beschützen. Davon sollte jeder erfahren... damit wir nie wieder zulassen, dass die Neruber uns so unter Zugzwang setzen.\n\nKehrt zu Merrix in Dornogal zurück. Sagt ihm, dass wir bald kommen. Wir... brauchen hier nur einen Moment.", sourceObjective = "Kehrt zu Merrix in Dornogal zurück.", completion = "Ihr lebt! Aber was ist mit den anderen?", sourceObjectiveStatus = "unverified-source-field" }
quests[78546] = { id = 78546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedergutmachung", description = "Das Echo der Explosion haben wir bis hierhin gehört.\n\nIch nehme an, Ihr wart siegreich, aber dass Ihr allein herkommt, bedeutet wohl, dass nicht alles gut ausging.\n\nWas ist geschehen?", sourceObjective = "Sprecht mit Adelgonn, um Merrix über Baelgrims Schicksal zu informieren.", progress = "Erzählt mir, was geschehen ist.", completion = "Möge Baelgrims Heldenmut uns allen ein Vorbild sein.\n\nEr gab sein Leben, um unser Volk zu bewahren - unsere Einheit. Wir dürfen nicht zulassen, dass sein Opfer vergeblich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[78555] = { id = 78555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterirdisch und überfordert", sourceObjective = "Helft den Maschinenflüsterern, die Sicherheit in Station Eisenhol wiederherzustellen.", progress = "Tote Neruberhuscher, nicht explodierte Bomben, verletzte Arbeiter... was für ein Chaos.", completion = "Danke, dass Ihr den Arbeitern wieder auf die Beine geholfen habt. Ihr habt die Ordnung wiederhergestellt, zumindest so weit, dass wir wieder an die Arbeit gehen können.\n\nAm besten lässt sich Vorarbeiter Uzjax mit einer soliden Arbeitsmoral beeindrucken, und das habt Ihr geschafft.\n\n*flüstert* ... Aber seid vorsichtig. Er ist loyal gegenüber den Machthabern, also sollten wir aufpassen, was wir sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78557] = { id = 78557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entgleisungen", description = "Sprecherin Brinthe erkannt. Fremdlinge, es gibt viel zu tun.\n\nEine unserer größeren Minenloren ist entgleist. Sie blockiert den Hauptknotenpunkt der Station.\n\nDie Produktivität meiner Arbeiter ist beeinträchtigt, die Abläufe sind suboptimal. Die Titanen haben uns hierher geschickt, um zu arbeiten, aber nicht alle meine Arbeiter arbeiten. Könntet Ihr uns wieder auf Kurs bringen?\n\nSeid vorsichtig. Ich sehe, dass Ihr aus Fleisch und Knochen besteht. Ich möchte nicht, dass Ihr zerquetscht werdet.", sourceObjective = "Untersucht die entgleiste Minenlore in Station Eisenhol.", progress = "Solange wir loyal sind, unsere Abgabetermine einhalten und unsere Quoten erreichen, ist alles in Ordnung.\n\nDie Rädchen drehen sich weiter und wir arbeiten weiter.\n\nDie Maschine sei gepriesen.", completion = "Bericht angefordert. Habt Ihr irgendetwas finden können? \n\nWas soll das sein? Ein \"Skar-dyn\"? \n\nDiese Information ist irrelevant für meinen Auftrag. Fokus liegt auf Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[78558] = { id = 78558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazarraserei", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78559] = { id = 78559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazarraserei - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78560] = { id = 78560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sholazarraserei - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78562] = { id = 78562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weggeworfen und zerbrochen", description = "Ihr da! Ihr seid hier, um zu helfen, richtig?\n\nDie summende Melodie der Maschinen verändert sich, und ich... ich muss zugeben, dass ich nicht bereit bin. So viele Jahre habe ich treu gedient, und dann...\n\nNun, das Wichtigste ist, dass ich bereit bin, wieder an die Arbeit zu gehen. Es ist nur so, meine Werkzeuge wurden alle zerstört und überall verteilt.\n\nWenn Ihr die Augen nach ihnen aufhalten und sie mir zurückbringen könntet, stünde ich in Eurer Schuld.", sourceObjective = "Sammelt Maschinist Kittrins verlorenen Werkzeuge ein.", progress = "Ein Maschinist ist nichts ohne seine Amtswerkzeuge.", completion = "Meine Anzeige! Mein Messschieber! Mein Schraubenschlüssel!\n\nEs fühlt sich gut an, sie wieder in der Hand zu haben. Auch wenn ich zugeben muss, dass ich nicht ganz ehrlich zu Euch war.", sourceObjectiveStatus = "unverified-source-field" }
quests[78563] = { id = 78563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gewicht einer Welt", description = "Meine Werkzeuge sind nicht zufällig dort gelandet, wo Ihr sie gefunden habt. Sie wurden dort platziert. Von mir.\n\nIch hatte einen solchen Tiefpunkt erreicht, dass ich keine andere Möglichkeit sah. Die Maschinen, das große Werk meines Volkes, würden nie wieder singen. Warum also sollte ich mich damit abmühen, sie immer wieder zu reparieren?\n\nAber nun sehe ich und nun verstehe ich!\n\nDas letzte Werkzeug, das ich brauche, habe ich ins Wasser geworfen und es wurde von einer riesigen Kreatur gefressen. Ich glaube, es wird ein wenig mehr Krafteinsatz erfordern, das zurückzuholen.", sourceObjective = "Holt Maschinist Kittrins kalibriertes Gewicht zurück.", progress = "Sobald ich all meine Werkzeuge wiederhabe, weiß ich, dass alles wieder gut wird.", completion = "<Kittrin scheint sich von all dem Eingeweideschleim auf seinem kalibrierten Gewicht nicht stören zu lassen.>\n\nIhr habt es gefunden! Ich muss es nur schnell säubern und meine anderen Werkzeuge reparieren. Dann bin ich wieder bereit zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78564] = { id = 78564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu geschmiedete Bestimmung", description = "Das sind alle! Jetzt ist es Zeit, meine Pflicht zu tun und diese Werkzeuge neu zu gießen, sie neu zu schmieden... und mich selbst neu zu schmieden zu dem, was ich sein sollte: ein stolzer Maschinist der Schallenden Tiefen.", sourceObjective = "Helft Maschinist Kittrin, die Werkzeuge neu zu schmieden und zu weihen.", progress = "Ich bin einmal mehr bereit, meinen Beitrag zu leisten. Ich muss nur diese alten Werkzeuge neu schmieden.", completion = "Ich kann mich gar nicht genug für all Eure Hilfe bedanken. Ich hatte schon den Glauben verloren, aber nun habe ich nicht nur meinen Glauben, sondern auch meine Werkzeuge zurück.\n\nIch werde Euch auf ewig dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78565] = { id = 78565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug in die malerischen Grizzlyhügel!", description = "Das heutige Sonderangebot ist ein magischer Ausflug in die majestätischen Wälder von Nordend!\n\nIhr gehört doch zu diesen Abenteurern, oder? Tut mir bitte einen Gefallen.\n\nKönntet Ihr mir ein paar Blumen in den Grizzlyhügeln pflücken? Ich habe alle Hände voll zu tun, aber ich muss dringend jemandem einen Blumenstrauß schenken.", sourceObjective = "Nehmt das Portal für malerische Ausflüge in die Grizzlyhügel, um einen Blumenstrauß für Gabbo zu pflücken.", progress = "Meine Partnerin würde sich wirklich über diese Blumen freuen.", completion = "Vielen lieben Dank, {name}!\n\nIch hoffe, Euch hat Euer Ausflug in die Hügel gefallen! Wo immer man hinschaut, gibt es etwas Neues zu entdecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[78570] = { id = 78570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschundenes Vermächtnis", description = "Bleibt Euch treu, {race}t.\n\nAls Woldgard halten wir unser altes Versprechen an Freya ein und hüten diese Länder. Unser Edikt ist älter als jene, die die Hetzer in Dornogal akzeptieren. Älter noch als Dornogal.\n\nDoch nicht alle Länder wurden in gleichem Maße behütet. Die Anführerin unseres Ordens sollte sich um das Becken unten kümmern, doch wir haben seit vielen Zyklen nichts mehr von ihr gehört.\n\nIch habe einen Neuling entsandt, um der Sache nachzugeben. Leistet Unterstützung und mein Orden ist Euch zu Dank verpflichtet.", sourceObjective = "Trefft Euch mit Igris am Holzwurzelbecken auf der Insel von Dorn.", completion = "Das Becken sollte nicht so aussehen. Wir haben viel Arbeit vor uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[78571] = { id = 78571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzplage", description = "Freydrin war die Anführerin meines Ordens. Ich wurde hergeschickt, um ihr zu helfen. Ich kam zu spät.\n\nIn diesen Wäldern treibt eine Finsternis ihr Unwesen, {race}s.\n\nDie Wälder waren Freydrins Zuhause. Es war ihre Aufgabe, sie zu hüten, aufgetragen von der Hüterin persönlich. Und jetzt ist sie fort und die Wälder versinken im Chaos.\n\nBringt mir die Sporen dieser zerstörerischen Plage. Vielleicht gibt es noch Hoffnung, dieses Land zu säubern.", sourceObjective = "Sammelt 30 Holzwurzelsporen von Fungianern im Holzwurzelbecken.", progress = "Habt Ihr sie alle?", completion = "Vielen Dank, {name}. Ich werde sie genauestens untersuchen. Die Fungianer in diesen Wäldern stellen eine größere Gefahr dar, als wir alle erwartet hatten.\n\nWir müssen ihre Ausbreitung verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78572] = { id = 78572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holtzerinnerungen", description = "Freydrin muss einen Weg gefunden haben, die Fungianer zu bekämpfen.\n\nAuch wenn im Land nur noch wenige den Edikten folgen, glaubte Freydrin doch für lange Zeit unerschütterlich daran. Sie hätte nie zugelassen, dass die Wälder in diesen Zustand geraten, solange sie noch am Glauben festhielt.\n\nWir sollten uns in ihrem Zuhause in den Wäldern umsehen. Vielleicht finden wir dort etwas, was uns weiterhilft.", sourceObjective = "Durchsucht Freydrins Zuhause, um besser für den Kampf gegen die Fungianer im Holzwurzelbecken gerüstet zu sein.", progress = "Die Dinge der Holtzhüterin zu durchstöbern, ist beunruhigend. So viele nie erzählte Geschichten.", completion = "Diesem Stab wohnt eine bekannte Magie inne, die ich nur zu gern vergessen würde. Oh, Freydrin, was ist hier geschehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[78573] = { id = 78573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hüterin zu Hilfe", description = "Ein magischer Stab? Schutze? Woran habt Ihr bloß gearbeitet, Freydrin?\n\n<Igris grübelt kurz, die Brauen über ihren leuchtenden Augen gerunzelt. Dann wendet sie sich Euch mit einem Lächeln zu.>\n\nIch hab's!\n\nDie Lebensenergie in diesem Stab sollte jegliche mykotische Verderbnis in den Lebewesen hier überwinden. Damit kehren sie zu ihrem natürlichen Lebenszyklus zurück und mit der Zeit heilt sich das Land von ganz allein.\n\nUnd wenn Ihr Schutze seht, nehmt sie ab. Und nehmt für alle Fälle ihren Erinnerungsedelstein mit. Vielleicht verrät er uns noch mehr.", sourceObjective = "Nutzt Freydrins Shillelagh, um das Holzwurzelbecken zu bereinigen.", progress = "Diesem Stab wohnt eine Menge latente Magie inne. Er ist vielleicht unsere einzige Hoffnung, um diese Fungianer in die Knie zu zwingen.", completion = "Einfach faszinierend.", sourceObjectiveStatus = "unverified-source-field" }
quests[78574] = { id = 78574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr im Holtz", description = "Um eine letzte Sache muss ich Euch noch bitten.\n\nIn diesen Wäldern treibt sich ein großes Monster herum. Ich bin sicher, Ihr habt es gespürt. Es muss erlegt werden.\n\nFaulborke war Freydrins letztes Mittel, um diesem Becken Herr zu werden, doch dieses Unterfangen war für einen einzelnen Irdenen zu groß. Unsere Aufgabe ist nicht zu kontrollieren, sondern uns um seine Bedürfnisse zu kümmern.\n\nSetzt den Stab ein weiteres Mal ein und setzt Faulborke ein Ende.", sourceObjective = "Besiegt Faulborke den Ungefällten im Holzwurzelbecken.", progress = "Wenn wir dieses Land wieder herrichten wollen, müssen wir es auf andere Weise tun. Wir müssen einen neuen Pfad schlagen.", completion = "Faulborkes Tod markiert das Ende der Verrottung, die sich in diesem Becken ausbreiten konnte.\n\nIch danke Euch, {race}. Eure Hilfe war unermesslich.", sourceObjectiveStatus = "unverified-source-field" }
quests[78579] = { id = 78579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
quests[78580] = { id = 78580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Dracheninseln", sourceObjective = "Eure Hilfe war entscheidend für die Wiederbelebung des Traums. Bitte nehmt dies als Belohnung für Eure Mühen. Danke für all die harte Arbeit, Champion.", sourceObjectiveStatus = "unverified-source-field" }
