quests[78589] = { id = 78589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasive Küche", description = "<Diese selten zu sehende Pflanze könnte für Chefkoch Dinaire von Nutzen sein.>", sourceObjective = "Bringt die Umbralaubergine zu Chefkoch Dinaire in den Fungusfeldern.\n\nBereitgestellter Gegenstand:", completion = "Eine Umbralaubergine entspricht vielleicht nicht jedermanns Vorstellung von leckerem Essen, aber wenn ich sie zubereite, ist sie ein Publikumsliebling!", sourceObjectiveStatus = "unverified-source-field" }
quests[78590] = { id = 78590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es braucht Schneid" }
quests[78591] = { id = 78591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug ins malerische Nagrand!", description = "Das heutige Sonderangebot ist ein magischer Ausflug in die großen Ebenen von Nagrand!\n\nWenn Ihr dorthin unterwegs seid, könntet Ihr ein paar Tiere für mich schießen? Oh nein, doch nicht so! Hier, borgt Euch meine Kamera.\n\nMeine Freundin Beatrice streift in letzter Zeit durch diese Gegend. Sie hätte wirklich gern ein paar Fotos, aber ich muss mich um Portale kümmern.", sourceObjective = "Nehmt das Portal für malerische Ausflüge nach Nagrand und macht dort Aufnahmen von Wildtieren für Beatrice.", progress = "Es gibt so viele Orte in Azeroth für einen Ausflug! Überall, wohin man schaut, gibt es etwas Neues zu entdecken.", completion = "Ich wusste, dass Beatrice sich über Eure Fotos freuen würden.\n\nDanke für Eure freundliche Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78594] = { id = 78594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausflug ins malerische Feralas!", description = "Das heutige Sonderangebot ist ein magischer Ausflug zu den sonnigen Stränden von Feralas! Im Hotel an den Dampfteichen wird ein wunderbares Fest gefeiert, und alle sind eingeladen!\n\nLeider haben einige der Partygäste, die schon durch das Portal sind, ihre Geschenke hier auf der Gala vergessen.\n\nKönntet Ihr mir helfen, sie ihnen zu bringen? Wir treffen uns am Strand und finden heraus, welches Geschenk wem gehört.", sourceObjective = "Nehmt das Portal für malerische Ausflüge nach Feralas und bringt die vergessenen Geschenke zu den entsprechenden Empfängern.", progress = "Es gibt so viele Orte in Azeroth für einen Ausflug! Überall, wohin man schaut, gibt es etwas Neues zu entdecken.", completion = "Danke für Eure Unterstützung, {name}! Ihr habt viele Gäste erfreut, weil Ihr ihnen ihre Geschenke gebracht habt.\n\nUnd was war das für eine Palette an Gaben! Vielleicht interpretiert jeder die Sprache der Liebe anders.", sourceObjectiveStatus = "unverified-source-field" }
quests[78595] = { id = 78595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauminfusion", description = "<Melsysra drückt Euch eine leicht feuchte Notiz in die Hand.>\n\n{name}, dank Euch haben wir jetzt genug Kraft für eine Trauminfusion! Trefft mich im Zentrallager, damit ich sie Euch bringen kann.\n\n- Elianna", sourceObjective = "Sprecht mit Elianna im Zentrallager.", completion = "Infusion frei!", sourceObjectiveStatus = "unverified-source-field" }
quests[78596] = { id = 78596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbestellung zu Lord Graumähne", description = "Seid gegrüßt, \n\nLord Graumähne bittet Euch zum Hafen von Sturmwind, um ihm bei einer Angelegenheit zu helfen, die Gilneas betrifft.\n\nMehr darf ich leider nicht sagen.\n\nViel Glück, {name}.", sourceObjective = "Trefft Euch mit Genn Graumähne im Hafen von Sturmwind.", completion = "Danke, dass Ihr gekommen seid, {name}.\n\nIch will Euch Eure Mission erläutern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78597] = { id = 78597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Bewegungen", description = "{name},\n\nLilian Voss und Calia Menethil erbitten Eure Teilnahme an einer Geheimoperation, die etwas mit Gilneas zu tun hat.\n\nNach Eurer Ankunft werdet Ihr vollumfänglich informiert.", sourceObjective = "Trefft Euch mit Lilian und Calia in Lohenscheit im Silberwald.", progress = "Ausgezeichnet, wir haben Euch schon erwartet.", completion = "Danke, dass Ihr gekommen seid, {name}.\n\nIch will Euch Eure Mission erläutern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78598] = { id = 78598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauminfusion", sourceObjective = "Dank Eurer Mühen haben wir jetzt genug Kraft für eine weitere Trauminfusion! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[78600] = { id = 78600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, Hoffnung des Traums: In Rauch aufgegangen", description = "Glimmeron scheint Fyrakks Angriff auf den Traum zu unterstützen! Wenn Ihr einige Fragmente von Glutnarbe, seiner legendären Waffe sammelt, können wir uns vielleicht auf ihre Energie einstimmen und seinen Thron direkt angreifen.", sourceObjective = "Sammelt 3 Fragmente von Glutnarbe von Glimmeron in Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad Normal.", progress = "Die Energie in diesen Fragmenten wird uns erlauben, schnell zum Thron des Feuerlords vorzudringen.", completion = "Das sollte uns erlauben, leichter zu Glimmerons Thron vorzudringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78601] = { id = 78601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, Hoffnung des Traums: In Rauch aufgegangen", description = "Glimmeron scheint Fyrakks Angriff auf den Traum zu unterstützen! Wenn Ihr einige Fragmente von Glutnarbe, seiner legendären Waffe sammelt, können wir uns vielleicht auf ihre Energie einstimmen und seinen Thron direkt angreifen.", sourceObjective = "Sammelt 3 Fragmente von Glutnarbe von Glimmeron in Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad Heroisch.", progress = "Die Energie in diesen Fragmenten wird uns erlauben, schnell zum Thron des Feuerlords vorzudringen.", completion = "Das sollte uns erlauben, leichter zu Glimmerons Thron vorzudringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78602] = { id = 78602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, Hoffnung des Traums: In Rauch aufgegangen", description = "Glimmeron scheint Fyrakks Angriff auf den Traum zu unterstützen! Wenn Ihr einige Fragmente von Glutnarbe, seiner legendären Waffe sammelt, können wir uns vielleicht auf ihre Energie einstimmen und seinen Thron direkt angreifen.", sourceObjective = "Sammelt 3 Fragmente von Glutnarbe von Glimmeron in Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad Mythisch.", progress = "Die Energie in diesen Fragmenten wird uns erlauben, schnell zum Thron des Feuerlords vorzudringen.", completion = "Das sollte uns erlauben, leichter zu Glimmerons Thron vorzudringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78607] = { id = 78607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Mereldar", description = "Wir müssen nach Mereldar und Generalin Stahlstoß mitteilen, was der Orden der Nacht hier versucht hat.\n\nDank der Heiligen Flamme konnten wir Schlimmeres verhindern.", sourceObjective = "Reist nach Mereldar und trefft Euch mit Generalin Stahlstoß.", completion = "Endlich, eine Gelegenheit zum Ausruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78608] = { id = 78608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermischer Galopp", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78609] = { id = 78609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermischer Galopp - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78610] = { id = 78610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geothermischer Galopp - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78613] = { id = 78613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bastion von Heilsturz", description = "Ich muss gestehen, dass ich nicht gedacht hätte, dass die ersten Gäste in Mereldar Fremde sein würden. Ich dachte, das Reich... Nun ja, vergessen wir das.\n\nIhr habt meinem Volk sehr geholfen und das verdient Anerkennung. Mereldar ist die Bastion der Arathi in Heilsturz. Nehmt Euch etwas Zeit, um Euch auszuruhen.", sourceObjective = "Erkundet Mereldar.", progress = "In dieser Stadt gibt es viel zu sehen.", completion = "Es war gut, sich eine Weile hinsetzen und durchatmen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[78614] = { id = 78614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mereldars Licht", description = "Ich brauche noch mehr Zeit mit Alleria, um mehr über Xal'atath zu erfahren. Was ich bisher weiß, ist sehr besorgniserregend.\n\nFaerin hat mitgeteilt, dass sie zum Waisenhaus geht. Sie möchte, dass Ihr sie dort trefft. \n\nWenn sie in Mereldar ist, unterhält sie dort oft die Kinder, und sie würde sich gewiss freuen, wenn Ihr das auch tun würdet.", sourceObjective = "Spielt mit 3 Waisen der Arathi.", progress = "Es ist schön zu sehen, wie glücklich diese Kinder sind nach allem, was sie durchgemacht haben.", completion = "Ich komme immer gern hierher, wenn ich in Mereldar bin. Die Kinder bringen mich immer zum Lächeln, und ich hoffe, dass es ihnen genauso geht.\n\nNach den furchtbaren Dingen, die sie erlebt haben, verdienen sie es, glücklich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78615] = { id = 78615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Glocke schlägt", description = "Das Glockenläuten bedeutet, dass Mereldar angegriffen wird!\n\nGehen wir zum Tor, um herauszufinden, was los ist.", sourceObjective = "Geht zum Haupttor von Mereldar in Heilsturz.", completion = "Dafür werden sie bezahlen, {name}. \n\nWir schlagen so hart zu, dass sie nie wiederkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78616] = { id = 78616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen: Die Geheimnisse des Observatoriums der Eintracht" }
quests[78618] = { id = 78618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pilzpsychose" }
quests[78620] = { id = 78620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreuzweg des Zwielichts", description = "Wir müssen die Ehrengründe von den Kobyss befreien.\n\nDrängt sie zurück und bahnt Euch einen blutigen Pfad durch ihre Reihen.\n\nWir müssen beenden, was auch immer an der Ewigen Flamme vor sich geht. Wenn es ihnen gelingt, sie wie seinerzeit am Turm zu verderben... dann will ich mir gar nicht ausmalen, was passiert.", sourceObjective = "Tötet 15 Angreifer der Kobyss auf den Ehrengründen in Heilsturz.", completion = "Jetzt müssen wir uns nur noch um den Schild kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78621] = { id = 78621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatten erhebt sich", description = "Ich spüre, dass sich drei Flammen der Leere vor uns befinden, die zusammen einen riesigen Quell der Dunkelheit mit Macht versorgen.\n\nIhr müsst sie ausschalten. Wenn sie erloschen sind, kann ich den Schild ausschalten.", sourceObjective = "Tötet die Tiefsprecher der Kobyss in den Ehrengründen in Heilsturz.", progress = "Ich bin bereit, das zu beenden.", completion = "Ausgezeichnet.\n\nUnd jetzt durchbrechen wir diesen Schild.", sourceObjectiveStatus = "unverified-source-field" }
quests[78624] = { id = 78624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kerze in der Dunkelheit", description = "Beledar hat sich dem Schatten zugewandt, wir müssen uns nach Mereldar zurückziehen!\n\n<Vaelisia blickt zu Aelric Leid herüber.>\n\nIch... Nein. Wir müssen zuerst Aelric vernichten.\n\nBringt ihn zu Fall, dann ziehen wir uns zurück.", sourceObjective = "Tötet Aelric Leid in den Ehrengründen in Heilsturz.", completion = "Das Licht segne Faerin.\n\nIch dachte schon, die Ewige Flamme wäre verloren.\n\nIch dachte, alle Hoffnung wäre vergebens und unser Volk zum Sterben verdammt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78626] = { id = 78626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparringtag", description = "Eure Kampffertigkeiten sind beeindruckend, {name}.\n\nWir rotieren gerade unsere nächsten Reservisten in den aktiven Dienst, aber ihre Fähigkeiten müssen noch geschärft werden.\n\nIch würde mich freuen, wenn Ihr uns mit ihrer Ausbildung helfen könntet, während ich mir Allerias Bericht über Xal'atath anhöre.", sourceObjective = "Duelliert Euch mit 8 Rekruten der Arathi in Mereldar.", progress = "Die Tricks, die sie heute von Euch gelernt haben, werden ihnen später in der Not das Überleben sichern.", completion = "Vielen Dank.\n\nWas sie von Euch gelernt haben, wird ihnen zukünftig ganz sicher das Leben retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78627] = { id = 78627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Front", description = "Kurz vor dem Angriff der Kobyss erfuhren wir von einer Störung in der Nähe von Livias Langmut. Jetzt kennen wir den Grund.\n\nWir... das Licht... Einen Zweifrontenkrieg überleben wir nicht, {name}. Wir müssen dem jetzt ein Ende bereiten.", sourceObjective = "Reist nach Lichtschanze in Heilsturz.", completion = "Flammen, sie haben Tunnel unter dem Seegrund gegraben.\n\nLivias Langmut ist bereits gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78628] = { id = 78628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falltürfederung", description = "Wir benötigen Zeit, um die Abrechnung vorzubereiten. Schart Eure Freunde um Euch und haltet die Neruber so lange wie möglich auf.\n\nFür ihre Schandtaten haben sie nichts als den Tod verdient.", sourceObjective = "Tötet 15 Neruber in Livias Langmut in Heilsturz.", progress = "Wie läuft die Jagd?", completion = "Gute Arbeit, {name}. Erstaunlich, dass die Neruber noch nicht die Flucht ergriffen haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[78629] = { id = 78629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Reserve", description = "Wir müssen versuchen, alle unsere Leute zu retten, die in Livias Langmut noch am Leben sind. \n\nJeder Arathi ist oder war ein Mitglied des Militärs. Wenn Ihr ihnen helfen könnt, werden sie sich selbst helfen können.", sourceObjective = "Helft 5 Reservisten der Arathi in Livias Langmut in Heilsturz.", progress = "Ich konnte zwar einige retten, aber habt Ihr auch jemandem helfen können?", completion = "Danke, {name}. Alleria, Anduin, Ihr und ich haben es geschafft, einige zu retten. \n\nDie Neruber haben viele der anderen entführt. Wir müssen ihnen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78630] = { id = 78630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Aufstieg der Abrechnung", description = "Die Abrechnung ist bereit!\n\nLassen wir diese Spinnen büßen. Blut für Blut.", sourceObjective = "Geht an Bord der Abrechnung und tötet 150 Neruber.", progress = "Wir werden dafür sorgen, dass die Neruber es bereuen, jemals auch nur daran gedacht zu haben, in unsere Heimat einzufallen!", completion = "Wie dumm wir sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[78631] = { id = 78631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit den Sprechern sprechen", description = "Ich habe in der Nähe von einem Problem gehört und ich glaube, ich weiß, was da los ist.\n\nWir hatten mal eine Mine nordöstlich von Gundargaz. Nachdem wir sie aufgegeben hatten, haben die Kobolde sie übernommen.\n\nWir haben lange Zeit nichts von diesen Kobolden gehört, aber es scheint, als würden sie uns jetzt überfallen! Und der Oberste Sprecher unternimmt nichts dagegen.\n\nIrgendjemand muss etwas tun. Wenn wir das Problem lösen können, dann werden uns mehr Maschinenflüsterer Gehör schenken. Wenn der Oberste Sprecher nichts erreicht, dann werden wir uns darum kümmern.", sourceObjective = "Beruhigt die Verteidiger von Gundargaz auf dem Weg zu den Verlorenen Minen.", completion = "Es ist gut, zu sehen, dass einige der Kobolde gar nicht so versessen auf diesen Krieg sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[78634] = { id = 78634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Stein wird zurückgelassen", description = "Viele Irdene fielen, als die Kobolde diese Mine übernahmen.\n\nUnd was noch schlimmer war: Die Gefallenen wurden dort, wo sie lagen, dem Verfall überlassen. Es wurde kein Versuch unternommen, sie zu bergen. Wir konnten ihnen kein würdiges Ende bieten oder ihre Erinnerungen ehren. Warum? Warum haben wir die Gefallenen im Stich gelassen?\n\nWir werden sie nicht noch einmal enttäuschen, {name}. Sammelt die Identifikationsplaketten von denen, die wir verloren haben, damit wir ihrer würdevoll gedenken können.", sourceObjective = "Bergt Identifikationsplaketten von gefallenen Irdenen in den Verlorenen Minen.", progress = "Habt Ihr sie gefunden?", completion = "Habt Dank, {name}. Den Gefallenen wird gedacht werden.\n\nDie Irdenen über uns haben ihre eigenen Gedenkrituale. Und die Maschinenflüsterer haben Verfahren eingerichtet.\n\nAuf dem Stadtplatz gibt es einen Sockel mit den Plaketten der Gefallenen. Jurlax wird sicherstellen, dass die richtigen Bräuche durchgeführt werden... zusammen mit Ablaufüberprüfungen und einer Neukalkulierung der Arbeiterverteilung. Die Arbeit hört hier nie auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[78635] = { id = 78635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod und Wachs", description = "Kobolde Kerzen ernst nehmen. Wachs noch mehr. Wichtiger als Gold. Wichtiger als Freiheit!\n\nWir Kerzen stehlen von Kerzenkönig. Durch uns er schwach erscheinen. Tyrann, der schwach erscheinen, Kontrolle verlieren. Wird tot!\n\nAuch wichtig: Wir nicht in Dunkelheit warten müssen für gefressen werden. Beeilung!", sourceObjective = "Bergt Flackerflammenkerzen überall bei den Verlorenen Minen.", progress = "Ihr Kerze genommen?", completion = "<Krabbler entspannt sich sichtbar in der Gegenwart der Kerzen.>\n\nAh, gut. Und jetzt mich hier rausholen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78636] = { id = 78636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung der Minen", description = "Da wir jetzt die Schlüssel haben, ist es Zeit, gegen den Kerzenkönig zu kämpfen.\n\nÖffnet das Tor. Sobald wir drinnen sind, machen wir den nächsten Schritt.", sourceObjective = "Öffnet das Tor zu den Verlorenen Minen.", completion = "Das... lief nicht wie erwartet.\n\nUnsere neue Koboldfreundin könnte einige bessere Ideen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[78637] = { id = 78637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahnradkauer knacken", description = "Zahnradkauer ist Mann fürs Grobe für Kerzenkönig. Richtig fies! Baut irdene Zahnräder für Kriege wieder auf. Und ist zuständig für Verteidigung der Mine.\n\nWir seine Schlüssel brauchen für in Minen kommen... und für mich hier rausholen!", sourceObjective = "Tötet Zahnradkauer in den Verlorenen Minen und bergt seine Schlüssel.", progress = "Ihr Schlüssel gefunden?", completion = "Danke, {name}. Hätte nicht gedacht, noch mal frei zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78638] = { id = 78638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstörte Ingenieurskunst", description = "Einige die Kobolde bauen die Ausrüstung um, die zurückgelassen wurde, als die Minen fielen.\n\nBitte zerstört die Ausrüstung, bevor sie gegen uns eingesetzt werden kann. Ich möchte sie lieber zerstört sehen als in den Händen unserer Feinde.\n\nEs gab ein Lager am westlichen Rand auf der niedrigsten Ebene der Mine. Fangt dort an zu suchen.", sourceObjective = "Zerstört Minenausrüstung in den Verlorenen Minen.", progress = "Ist noch irgendwas funktionsfähig, {name}?", completion = "Vielen Dank. Unsere Gegner haben jetzt einen Vorteil weniger.", sourceObjectiveStatus = "unverified-source-field" }
quests[78639] = { id = 78639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kühne Kobolde", description = "Überall Grobiane!\n\nUnschuldige Kobolde unterdrückt von Schlägern von Kerzenkönig überall im Hasenbau.\n\nGrobiane sollen eigene Schikane spüren!\n\nWenn Grobiane geschlagen, Unschuldige haben Chance für entkommen. Für frei sein!", sourceObjective = "Befreit unterdrückte Kobolde im Hasenbau, indem Ihr ihre Unterdrücker bezwingt.", completion = "Ist Anfang. Vielen Dank. Ist Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[78640] = { id = 78640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksalsmanifest", description = "Vor Eroberung der Minen mein Volk in großer Stadt leben. Steinköpfe es Hasenbau nennen.\n\nSchläger von Kerzenkönig jetzt Sagen haben. Wir sehen müssen, wogegen wir kämpfen. Kobolde wissen müssen, wir hier für helfen! Wir besser als Kerzenkönig.\n\nWas besser als Flugblätter? Alle Flugblätter lieben! Wir richtig gut malen können!\n\nBrinthe sagt, Ihr so Art fliegendes Drachen-Vogel-Ding haben? Perfekt für auskundschaften! Perfekt für auswerfen von Flugblättern!\n\n<Krabbler sieht Euch erwartungsvoll an und macht kleine Flatterbewegungen, während sie wartet.>", sourceObjective = "Macht einen Erkundungsflug und verteilt Flugblätter im Hasenbau.", progress = "Ich noch nie geflogen. Macht Spaß?", completion = "Traurig für Zuhause in so einem Zustand sehen.\n\nAber wir reparieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[78641] = { id = 78641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein langes Fackeln mit Fackelfletscher", description = "Fackelfletscher Aufgaben für Kerzenkönig erledigen. Er nur ein großer Grobian! Sehr, sehr großer Grobian.\n\nWir allen zeigen, man kann Grobiane besiegen!", sourceObjective = "Besiegt Fackelfletscher im Hasenbau.", progress = "Fackelfletscher der Große sein. Nicht wissen, warum er sich verstecken hinter seinen Handlangern. Aber Ihr ihn nicht übersehen können!", completion = "Schade, er entkommen. Aber alle anderen? Sehen, was er für ein Feigling! Auch gut.\n\nIch groß, deswegen ich gute Wörter haben. Er riesig! Er noch gutere Wörter haben sollte! Nicht sehr klug.", sourceObjectiveStatus = "unverified-source-field" }
quests[78642] = { id = 78642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Kerze, neue Hoffnung", description = "Wir schwächen Einfluss von Kerzenkönig. Brauche aber noch Zeichen, mein Volk zu versammeln.\n\nKönig hat altes Relikt: Zeichen der Hoffnung. Heißt Kerzenkrone. Herz meines Volkes. Kerzenkönig hat weggeworfen! Hat neue Beute gefunden: Dunkelflammenkerze.\n\nDie Krone? Noch in Hort. Kerzenkönig soll jetzt rauskommen. Sehen, was wir hier gemacht haben!\n\nWährend er schaut, wir können reinschleichen! Die alten Tunnel benutzen! Nehmen, was uns gehört! Wir klug.", sourceObjective = "Bergt die Kerzenkrone aus dem Dunkelflammenspalt.", completion = "Ha! Wir es geschafft! Alle jetzt wissen: Kerzenkönig nicht einziger Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[78643] = { id = 78643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klare Himmel und starke Winde", sourceObjective = "Sprecht mit Alexstrasza beim Sitz der Aspekte in Valdrakken.", progress = "Die Dracheninseln stehen in Eurer Schuld.", completion = "Klare Himmel und starke Winde, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78645] = { id = 78645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Begraben im Flussbett" }
quests[78646] = { id = 78646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwacht", description = "Meine Mutter scheint sich nicht vollständig auf das Auge einstimmen zu können. Vielleicht spürt es ihre Verbindung zum Ardenwald...\n\nIhr Schild ist nur ein Bruchteil der Macht des Auges. Wenn sie sich vollständig einstimmen könnte, könnte sie die Flammen unserer Feinde auslöschen.\n\nAber wir können nicht einfach abwarten. Wir brauchen mehr Informationen über Galok und seinen Angriffsplan. Bodwin gibt an, dass es eine Welle neuer Aktivität in Igiras Operationsbasis gibt. Mit Bodwins Hilfe können wir es untersuchen, ohne gesehen zu werden.", sourceObjective = "Trefft Euch mit Merithra am Rand des Auges von Ysera, mit Blick auf die Schlackenschlagfestung.", completion = "Das wird nicht leicht...", sourceObjectiveStatus = "unverified-source-field" }
quests[78649] = { id = 78649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Etwas Großes unterm Flussbett" }
quests[78655] = { id = 78655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adaptive Kühlsalbe", description = "Solltet Ihr meine Hilfe benötigen, kann ich Euch eine Salbe herstellen, die Euch bei der Einstimmung auf Fyr'alath helfen sollte.\n\nBringt mir die Materialien, die ich nicht habe, dann kann ich Euch sicherlich etwas zusammenmischen.", sourceObjective = "Bringt ErdenZaralekleuchtsporen, erweckten Frost und eine träumende Essenz für die adaptive Kühlsalbe.", progress = "Nur weiter so. All diese harte Arbeit wird sich auszahlen.", completion = "Perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78656] = { id = 78656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herunterspülen", description = "Nachdem die Flamme wiederhergestellt wurde, könnt Ihr nun das Ausmaß der Verschmutzung im Angelloch sehen. Kobyss und Frösche haben einen Haufen merkwürdigen Schleim zurückgelassen, der die Küste verunreinigt.\n\nWir brauchen Eure Hilfe dabei, diese Schleimpest zu beseitigen! \n\nIch habe einen speziell modifizierten Ernter, der mit einem Wasserfass ausgerüstet ist. Verwendet dieses Gerät, um Wasser auf die Schleimhaufen zu sprühen und die Küste von diesem Schmutz zu befreien.", sourceObjective = "Aktiviert Faeny das Fass und beseitigt mit dem Schlauch 40 Glibberkontanimierungen.", completion = "Gute Arbeit, {name}. Jetzt ist es hier gleich wesentlich schöner!", sourceObjectiveStatus = "unverified-source-field" }
quests[78657] = { id = 78657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mitternachtswache" }
quests[78658] = { id = 78658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der heilige Weg", sourceObjective = "Trefft Euch mit den Einwohnern von Heilsturz.", completion = "Freundliche Fremde sieht man nur selten in Heilsturz. Nur Feinde, die aus den Schatten springen.\n\nAber Euch scheint es im Licht gut zu gefallen, auch wenn Ihr eigenartig ausseht. Ich würde Euch ja gerne willkommen heißen, aber wir befinden uns inmitten einer Krise.", sourceObjectiveStatus = "unverified-source-field" }
quests[78659] = { id = 78659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo das Licht erstrahlt", description = "Viele in Heilsturz würden Euch einen \"Fremdling\" nennen. Ich nenne Euch einen Freund. Außerdem möchte ich Euch um Hilfe bitten, falls Ihr im Kampf erfahren seid. In verzweifelten Zeiten entstehen starke Freundschaften.\n\nGeneralin Stahlstoß hat der Armee befohlen, sich vor dem nerubischen Ansturm zurückzuziehen. Dadurch wurden ein Lampenanzünder und viele Truppen in der Dunkelheit zurückgelassen. Ich kann sie nicht allein retten, aber mit Eurer Hilfe könnte es mir gelingen.\n\nWenn Ihr bereit seid, reitet mit mir oder trefft mich dort.", sourceObjective = "Trefft Euch mit Faerins Verbündeter bei der Aegismauer.", completion = "Fremdling! Die Neruber haben uns überrascht. Die Armee hat sich zurückgezogen, als die Mauer durchbrochen wurde. Ich habe sie von diesem Turm ferngehalten, aber ich könnte wirklich Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78661] = { id = 78661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Schätze in der Klippe" }
quests[78662] = { id = 78662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Eine Klippe voller Lager" }
quests[78663] = { id = 78663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabung: Verteilt um den Turm" }
quests[78664] = { id = 78664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe der Selbstfürsorge", description = "Die Augen eines müden Abenteurers.\n\nJemand, der zu viel Großartiges für andere getan hat. Wann war das letzte Mal, dass Ihr Euch selbst etwas Gutes getan habt?\n\nVielleicht ist die Zeit jetzt gekommen. Erkundet Euer Herz.\n\nWas ist EUER Begehr?", sourceObjective = "Sprecht mit Ying, um Euren Herzenswunsch zu entdecken.", completion = "Treten wir Eure Reise zur Selbstliebe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[78665] = { id = 78665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunneltücke", description = "Es ist gut, hier neue Verbündete zu haben. Zusammen haben wir viel bessere Chancen, diesen Turm zu beschützen.\n\nDie Neruber haben uns überwältigt. Wenn wir eine Chance gegen sie haben wollen, müssen wir die Höhlen zerstören, über die sie unter die Mauer gelangen.\n\nWenn Euch das gelingt, werden wir das Feld von der Mauer aus überwachen und treffen Euch dort.", sourceObjective = "Zerstört 6 Nerubergräben.", progress = "Ist es Euch gelungen, den unterirdischen Vormarsch der Neruber aufzuhalten?", completion = "Ausgezeichnet, {name}. Wenn wir keine Angst mehr davor haben müssen, dass die Neruber uns in den Rücken fallen, können wir uns um die kümmern, die unten durchströmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78666] = { id = 78666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eine tote Spinne...", sourceObjective = "Tötet 12 Angreifer der Neruber.", completion = "Das ist ein guter Anfang. Aus dem Untergrund dringen nach wie vor jede Menge Neruber hervor, aber wir müssen uns zunächst um die kümmern, die bereits in Heilsturz sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[78667] = { id = 78667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfachtes Andenken", sourceObjective = "Bergt 6 Arathizunderkästen von gefallenen Soldaten und verbrennt ihre Leichen.", progress = "Konntet Ihr die Zunderkästen bergen? Ein jedes Leben hat es verdient, durch die Heilige Flamme in Erinnerung zu bleiben.", completion = "Vielen Dank, {name}. Ihr habt dafür gesorgt, dass ihr Opfer so gut wie möglich gewürdigt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[78668] = { id = 78668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammeln auf der Morgenbringer", description = "Es strömen so viele Neruber durch die Aegismauer, dass wir unsere in Tenirs Aufstieg angedockten Luftschiffe verteidigen müssen.\n\nWir sind den Nerubern stets zahlenmäßig unterlegen, doch unsere Flotte ermöglicht es uns, unsere Verteidiger dort zu konzentrieren, wo wir angegriffen werden! Außerdem können wir den Gegner so unbeschadet von oben bombardieren.\n\nWenn wir unsere Armada verlieren, schwindet unsere Hoffnung drastisch. Wir treffen uns dort, sobald Ihr könnt.", sourceObjective = "Trefft Euch mit Faerin bei Tenirs Aufstieg an Bord der Morgenbringer.", completion = "Ich freue mich, Euch an unserer Seite zu sehen, {name}.\n\nOhne unsere Luftschiffe stehen die Aussichten schlecht, dass wir die Neruber noch lange aufhalten können.\n\nGanz zu schweigen vom Schutz unserer Dockarbeiter, die sich bereits unter Deck in Sicherheit begeben haben.\n\nAlso, kümmern wir uns um die Verteidigung.", sourceObjectiveStatus = "unverified-source-field" }
quests[78669] = { id = 78669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur für ihre Augen", sourceObjective = "Sammelt 3 nerubische Schattenwirker, um ihre Pläne in Erfahrung zu bringen.", completion = "Endkrieg? Aufstieg? Mehr Fragen als Antworten, {name}, aber zumindest wissen wir mehr als vorher.", sourceObjectiveStatus = "unverified-source-field" }
quests[78670] = { id = 78670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerungswaffensabotage", sourceObjective = "Zerstört 4 Belagerungswaffen unterhalb von Tenirs Aufstieg.", progress = "Konntet Ihr die Belagerungswaffen zerstören, {name}?", completion = "Nachdem diese Belagerungswaffen zerstört sind, sieht es für uns schon viel besser aus. Faerin hat sich bereits zusammen mit dem Großen Kyron aufgemacht, um das Licht des Dämmerturms zu entzünden. Sie hat uns gebeten, sie dort zu treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78671] = { id = 78671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht des Dämmerturms", sourceObjective = "Unterstützt die Lampenanzünder dabei, das Licht des Dämmerturms zu entzünden.", completion = "Gerade zur rechten Zeit, {name}. Beledars Licht ist für den Moment erloschen, aber jetzt haben wir unsere eigene Lichtquelle, um der Dunkelheit Einhalt zu gebieten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78672] = { id = 78672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht eines Lampenanzünders", description = "Die Dunkelheit ist über uns hereingebrochen. Keine Zeit zum Ausruhen.\n\n<Faerin lächelt Euch müde an, aber sie hat ein Leuchten in den Augen.>\n\nDas Licht des Turms wird die größten Gefahren in der Dunkelheit fernhalten. Es ist meine Pflicht als Lampenanzünderin, dafür zu sorgen, dass keines der Lichter je ausgeht.\n\nLorels Kreuzung ist der nächste Halt auf meiner Patrouille durch die Luft. Ich würde es begrüßen, wenn Ihr und Anduin mich begleitet... zu unser aller Wohl.", sourceObjective = "Nehmt das Lampenanzünderboot, um Lorels Kreuzung zu erreichen.", completion = "Die Kobyss haben bereits unschuldige Dorfbewohner zum Ufer verschleppt! Sie werden sie ertränken und dann auffressen!\n\nWir müssen sie retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[78674] = { id = 78674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe der Erholung", description = "Ihr Abenteurer seid dafür bekannt, schwere Bürden zu schultern. Es gibt keinen besseren Zeitpunkt als jetzt, um sich ihnen zu stellen.\n\nIch habe hier irgendwo in der Nähe einen Veteranen gesehen. Es besteht die Möglichkeit, dass er weiß, was es heißt, Stress zu bewältigen.\n\nVielleicht gibt es etwas, dass er Euch beibringen kann.", sourceObjective = "Sprecht mit Simeon Griswold auf der Gala der Geschenke und baut dann Euren Stress in der Altstadt ab.", progress = "Ich habe Männer an Stress sterben sehen. Man darf ihn nicht jeden Tag unterdrücken.", completion = "Fühlt Ihr Euch besser?\n\nNach einem harten Tag müsst Ihr Euch pflegen. Seid gut zu Eurem Körper und Geist, dann werden sie gut zu Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78679] = { id = 78679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gabe der Entspannung", description = "Selbstliebe umspannt viele verschiedene Formen. Gelegentlich auch die Form der Entspannung.\n\nDer Nachtelf beim Feuerwerk wirkt ausgesprochen entspannt.\n\nVielleicht könnt Ihr ihn zu seinen Erkenntnissen hinsichtlich Entspannung befragen.", sourceObjective = "Sprecht mit Bordol Taugarten über Entspannung und entspannt Euch dann an Olivias Teich in Sturmwind.", progress = "Wahre Liebe bedeutet, den Eigenschutz aufzugeben. Gestattet Euch die Entspannung, dann versteht Ihr schon.", completion = "Ihr fühlt Euch erneuert, nicht wahr? Ich selbst streichle gerne Schildkröten.\n\nHabt Ihr schon eine Entspannungstechnik für Euch entdeckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[78685] = { id = 78685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende des Tunnels", description = "Wir haben weitere Gerüchte über Taelloch gehört.\n\nDie Stadt und ihre Mine sind verantwortlich für die Erzherstellung. Offenbar haben wir seit Wochen keine Lieferungen mehr erhalten und die Vorarbeiterin der Stadt ist verschwunden. Jetzt rät der Oberste Sprecher allen davon ab, dort hinzureisen.\n\nDas sagt mir, dass wir das untersuchen sollten. Und wenn Leute leiden, dann sollten wir selbstverständlich helfen.", sourceObjective = "Untersucht die Gerüchte um Taelloch.", completion = "Da sind Bestien drin?\n\nDie Einwohner von Taelloch könnten unsere Hilfe brauchen.\n\nHelft mir, ein Auge auf Dagran zu haben, {name}. Er hat viele aufregende Abenteuergeschichten gelesen, aber er hat nicht gesehen, was wir gesehen haben.\n\nUnd irgendetwas... stimmt hier nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[78686] = { id = 78686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht aus", description = "Ich bin Aegor. Ich will die Lampenanzünder im Feld im Auge behalten und sehen, welche Gebiete in Heilsturz ihre Hilfe brauchen könnten.\n\nDer Dämmerturm in Velhans Geltung ist vor ein paar Wochen dunkel geworden. Nach dem, was in der Umgebung von Heilsturz passiert ist, liegt das wahrscheinlich an der steigenden Flut von Kobyss.\n\nDie Lampenanzünder Taenar und Aemyra sind auf dem Weg dorthin, aber das könnte mehr sein, als zwei Lampenanzünder zusammen schaffen können. Trefft Ihr sie dort und helft ihnen, das Licht in Velhans Geltung wiederherzustellen?", sourceObjective = "Trefft Euch mit Taenar und Aemyra in der Nähe von Velhans Geltung.", completion = "Freut mich, Euch kennenzulernen, {name}. Ich bin Taenar, und das ist Aemyra.\n\nDer Dämmerturm in Velhans Geltung ist vor einer Weile dunkel geworden, und bei all dem, was passiert ist, sind wir erst jetzt angekommen, um zu helfen.\n\nWir haben ein wenig ausgekundschaftet, und wie es aussieht, ist die Gegend von Kobyss überrannt. Ich vermute, Velhan hat sich dort verkrochen, anstatt sie zu bekämpfen.\n\nWie gut für sein Volk, dass wir hier sind. Und es ist noch besser, dass Ihr dabei seid und helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[78687] = { id = 78687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absturzbergung", sourceObjective = "Beschafft 4 geborgene Zunderkästen von den Getreuen der Unbeugsamen.", progress = "Habt Ihr die Zunderkästen gefunden, {name}?", completion = "Die Flamme brennt für uns alle, {name}. Ich wünschte, ich hätte sie in dieser Nacht retten können, aber ich bin froh, dass wir ihr Andenken in Ehren halten können.\n\nDas würden wir uns alle wünschen, wenn es uns passieren würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[78688] = { id = 78688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käfige in Flammen", description = "Als wir vor Eurer Ankunft die Gegend erkundet haben, haben wir eine Menge Käfige um Velhans Geltung herum gesehen. Die Kobyss halten darin für gewöhnlich ihre Opfer gefangen, bis sie sie für eine rituelle Opferung benötigen.\n\nBei diesen Opferungen... geschehen allerlei andere finstere Dinge, nicht zuletzt das Verspeisen der Opfer.\n\nWir werden das nicht zulassen. Nehmt meine Fackel an Euch und zerstört die Käfige, damit niemanden aus Velhans Geltung dieses Schicksal ereilt.", sourceObjective = "Brennt 10 Käfige der Kobyss mit Aemyras Heiliger Flamme nieder.", completion = "Gute Arbeit, {name}. Ohne ihre Käfige können die Kobyss keine Gefangenen machen.\n\nKeine Gefangenen bedeutet keine üblen Rituale. Und wenn wir diese verhindern, haben wir eine viel bessere Chance, die Menschen in Velhans Geltung zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78689] = { id = 78689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auch Anführer bluten", sourceObjective = "Besiegt die Anführer der Kobyss, die Velhans Geltung belagern.", progress = "Habt Ihr die Anführer gefunden? Sie sehen stark aus, aber Ihr seid ihnen sicher gewachsen.", completion = "Ausgezeichnet. Damit wird das Kräfteverhältnis etwas ausgeglichener. Zumindest, was die Führung angeht.\n\nSie sind uns zahlenmäßig immer noch gewaltig überlegen, aber eins nach dem anderen.", sourceObjectiveStatus = "unverified-source-field" }
